// ImageJ学習アプリ 第3ラウンド追加データ：ドキュメント（独自要約・解説）と強化用語集。
// 権利方針：ImageJ User Guide等の本文の翻訳・転載は行わない。本文はすべて一次情報を参照して新規に書き起こした独自要約・解説であり、各項目に出典（公式資料名・URL・対象バージョン）を明示する。
window.IJDATA2 = window.IJDATA2 || {};
window.IJDATA2.docs = [
{id:"D1",title:"入門と画面構成",intro:"ImageJとFijiの関係、操作の対象になる「アクティブ画像」の考え方、取り消しの限界など、すべての操作の前提になる基礎をまとめる。",entries:[
{id:"D1-1",title:"ImageJとFijiはどう違うか",menu:"—（配布形態の違い）",body:["ImageJは米国NIHで開発された画像処理・解析プログラム本体であり、パブリックドメインとして公開されている。FijiはそのImageJを土台に、ライフサイエンス分野でよく使うプラグイン群と更新管理の仕組みを同梱した配布形態で、「Fiji Is Just ImageJ」の略称である。","そのため、基本操作・メニュー構成・測定の考え方は両者で共通する。本リファレンスの説明は原則として両者に当てはまるが、プラグインの有無や更新方法など配布形態に依存する部分は、その都度区別して記す。"],points:["ImageJ＝本体、Fiji＝本体＋プラグイン同梱の配布形態","基本操作と測定原理は共通","プラグイン構成と更新方法はFiji固有の話題になりやすい"],caution:"画面やメニューの細部はバージョンにより異なる。手元の環境と異なる場合は、その差異自体を記録しておくと再現性の確保に役立つ。",src:"https://imagej.github.io/imagej-wiki-static/User_Guide/Working_with_ImageJ.html",srcName:"ImageJ User Guide「Working with ImageJ」",version:"User Guide 1.46r（2012）時点の記述を含む。配布形態の関係は現行版でも変わらない。",lessons:["L01"],terms:["Fiji","アクティブ画像","プラグイン"]},
{id:"D1-2",title:"アクティブ画像：すべての操作は最前面の1枚に対して行われる",menu:"—（ウィンドウのフォーカス）",body:["ImageJでは、タイトルバーがアクティブになっている最前面の画像ウィンドウが、処理・計測・保存などすべての操作の対象になる。複数の画像を開いているとき、意図しない画像が対象になる事故は、解析ミスの典型的な原因のひとつである。","マクロでは getTitle() でアクティブ画像のタイトルを取得でき、処理対象を明示的に確認・切り替える記述が可能である。手作業でも、処理の直前にタイトルバーを確認する習慣が重要になる。"],points:["操作対象は常にアクティブな1ウィンドウ","処理前にタイトルを確認する","マクロでは getTitle() や selectWindow で対象を明示できる"],caution:"非アクティブな画像を見ながら操作すると、別の画像を加工してしまう。元画像は複製してから処理するのが安全である。",src:"https://imagej.github.io/imagej-wiki-static/User_Guide/Working_with_ImageJ.html",srcName:"ImageJ User Guide「Working with ImageJ」",version:"User Guide 1.46r 時点の記述。現行1.54系でもこの原則は変わらない。",lessons:["L01","L14"],terms:["アクティブ画像"]},
{id:"D1-3",title:"Undo（取り消し）は直近の1操作だけが対象",menu:"Edit > Undo",body:["ImageJの Undo は、基本的に直近の画像編集・フィルタ操作に限られ、それより前の操作へさかのぼって取り消すことはできない。一般的なアプリケーションのような多段階の履歴 undo ではない。","したがって、破壊的な処理（画素値を書き換える処理）を行う前には、画像を複製するか、ROIや測定条件などの中間成果を保存しておくことが、実務上の安全策になる。"],points:["取り消せるのは直近の操作のみ","破壊的処理の前に複製する","ROI・設定は別途保存しておく"],caution:"フィルタ適用や型変換のあとで保存して閉じると、元データには戻れない。元ファイルは上書きしない運用が原則である。",src:"https://imagej.github.io/imagej-wiki-static/User_Guide/Working_with_ImageJ.html",srcName:"ImageJ User Guide「Working with ImageJ」",version:"User Guide 1.46r 時点の記述。現行版でも多段階 undo には対応していない。",lessons:["L01"],terms:["Undo","ROI"]},
{id:"D1-4",title:"コマンドレコーダ：GUI操作をマクロとして記録し、操作の意味を調べる",menu:"Plugins > Macros > Record...",body:["コマンドレコーダは、GUIで行った操作を記録し、run() 呼び出しを中心とするマクロコードとして生成する機能である。繰り返し処理を自動化する第一歩であると同時に、「このメニュー操作が内部でどのコマンドに対応するか」を知るための公式な調べ方でもある。","記録されたコードをそのまま使うだけでなく、対象画像の指定やパラメータを書き換えて使うことで、手作業の手順を再現可能な形に残せる。"],points:["操作は run() 呼び出しとして記録される","自動化の起点であり、コマンド名の確認手段でもある","パラメータ文字列を編集して条件を固定できる"],caution:"記録には、そのときアクティブだった画像への操作も含まれる。別画像へ適用するときは対象の指定を確認すること。",src:"https://imagej.net/ij/docs/menus/plugins.html",srcName:"ImageJ公式「Plugins Menu」解説",version:"現行の imagej.net 掲載解説に基づく。レコーダの基本仕様は1.46r時代から継続している。",lessons:["L14"],terms:["コマンドレコーダ",".ijm / マクロファイル"]}
]},
{id:"D2",title:"画像の種類とビット深度",intro:"ビット深度は「1ピクセルがどれだけの情報を保持できるか」を決める。測定値の意味、変換で失われる情報、RGBとグレースケールの違いを整理する。",entries:[
{id:"D2-1",title:"8-bit / 16-bit / 32-bit float：保持できる値の範囲と性質",menu:"Image > Type",body:["8-bit画像は1ピクセルあたり256階調（0〜255の整数）、16-bit画像は65,536階調（0〜65,535の整数）を保持する。整数型では小数や負の値は表現できない。","32-bit画像は浮動小数点数で値を保持し、値の範囲に事実上の制限がなく、負の値や計算途中の小数、NaN（非数）も入り得る。演算結果を切り捨てずに保持したい場合は32-bitが適する。","ビット深度が大きいほど階調は細かくなるが、元の取得データに存在しない情報が増えるわけではない。変換は表現形式の変更であり、情報の追加ではない。"],points:["8-bit＝256階調、16-bit＝65,536階調、いずれも整数","32-bit float＝小数・負値・NaNを保持可能","深度を上げても失われた階調は復元しない"],caution:"表示上の見た目はLUTや表示範囲で調整されるため、深度の違いが見た目に直結するとは限らない。数値で確認すること。",src:"https://imagej.github.io/imagej-wiki-static/User_Guide/Working_with_ImageJ.html",srcName:"ImageJ User Guide「Working with ImageJ」",version:"User Guide 1.46r 時点の記述。現行1.54系でも各型の仕様は同一である。",lessons:["L02"],terms:["8-bit画像","16-bit画像","32-bit画像","グレー値"]},
{id:"D2-2",title:"RGB画像の測定値は何を表すか",menu:"Image > Type / Analyze > Measure",body:["RGB画像は赤・緑・青の3チャンネルが各256値を持つ24-bitカラー画像（アルファ付きは32-bit）である。RGB画像に対してそのまま測定を行うと、チャンネルごとの値ではなく、輝度として合成された値が扱われる場面があるため注意が要る。","チャンネルごとに定量したい場合は、Image > Color > Split Channels で各チャンネルをグレースケール画像に分けてから測定するのが確実である。ヒストグラム表示でも、RGB画像は輝度へ変換した分布として表示される。"],points:["RGBは3チャンネル×256値のカラー表現","定量はチャンネル分離後のグレースケールで行うのが確実","RGBのヒストグラムは輝度変換後の分布"],caution:"カラー写真の見た目の明るさと、測定される輝度は人間の視感度に基づく重み付けを含む場合がある。蛍光画像の定量にRGB化した画像を使ってはいけない。",src:"https://imagej.github.io/imagej-wiki-static/User_Guide/Working_with_ImageJ.html",srcName:"ImageJ User Guide「Working with ImageJ」",version:"User Guide 1.46r 時点の記述。現行版でもチャンネル分離して測定する原則は同じである。",lessons:["L02","L21"],terms:["RGB画像","チャンネル","ヒストグラム"]},
{id:"D2-3",title:"ビット深度を下げると何が失われるか",menu:"Image > Type",body:["16-bitから8-bitへの変換では、65,536階調が256階調へ圧縮（量子化）され、中間の階調情報は失われる。暗部のわずかな強度差や、飽和寸前の明部の差などが同一値に潰れ、後から16-bitへ戻しても復元しない。","変換時のスケーリング方法によっては、値の対応関係自体が変わる。解析に使う画像は、取得した元のビット深度のまま保持し、表示用・提出用に変換したコピーと区別することが重要である。","逆に、8-bitから16-bit/32-bitへ上げても情報は増えない。ただし、以降の演算で小数を保持したい場合は32-bit化に意味がある。"],points:["深度を下げると階調が潰れ、元に戻らない","変換時のスケーリングで値の対応が変わり得る","解析用は元深度で保持し、変換はコピーで行う"],caution:"「見た目が変わらない」ことと「数値が保たれる」ことは別である。定量解析前の安易な8-bit化は避けること。",src:"https://imagej.github.io/imagej-wiki-static/User_Guide/Working_with_ImageJ.html",srcName:"ImageJ User Guide「Working with ImageJ」",version:"User Guide 1.46r 時点の記述。量子化による情報損失の原理は現行版でも同一である。",lessons:["L02"],terms:["16-bit画像","8-bit画像","量子化","ダイナミックレンジ"]},
{id:"D2-4",title:"型変換（Type変換）で起きる値の変化",menu:"Image > Type",body:["Image > Type の変換では、対象の型に合わせて値が再解釈・丸め・スケーリングされる。整数型への変換では小数が切り捨てられ、範囲外の値は上限・下限に張り付く。8-bitの Math 系処理でも同様に、255を超える結果は255に、0未満は0に丸められる。","浮動小数を含む演算を正確に行いたい場合は、先に32-bitへ変換してから処理するのが原則である。Image Calculator の「32-bit Result」指定もこの考え方に基づく。"],points:["整数化では小数切り捨てと範囲外の飽和が起きる","正確な演算は32-bit化してから行う","変換は複製画像で試し、値の変化を確認する"],caution:"変換ダイアログのスケーリング設定は結果を大きく左右する。設定を記録せずに変換すると再現性が失われる。",src:"https://imagejdocu.list.lu/gui/process/math",srcName:"ImageJ Documentation Wiki「Math」",version:"imagejdocu の現行記載に基づく。丸めの仕様は User Guide 1.46r 時代から継続している。",lessons:["L02","L13"],terms:["32-bit画像","Math（Process > Math）","飽和"]},
{id:"D2-5",title:"グレー値（画素値）と実測値の関係",menu:"Analyze > Measure（値の解釈）",body:["グレー値（画素値）は、検出器が記録した信号を数値化したものであり、それ自体は物理量ではない。蛍光強度、透過光の吸収など、取得条件（露光、ゲイン、光源強度）が変われば、同じ対象でもグレー値は変わる。","したがってグレー値の比較は、取得条件をそろえた画像同士でのみ意味を持つ。背景差し引きや校正は、この相対比較を成立させるための手続きであり、絶対量への変換とは別問題である。"],points:["グレー値は信号の相対的な大きさを表す数値","比較は取得条件をそろえた画像間でのみ有効","物理量への変換には別途の校正が必要"],caution:"異なるセッション・異なる装置で得たグレー値を、そのまま絶対比較してはいけない。",src:"https://imagej.github.io/imagej-wiki-static/User_Guide/Working_with_ImageJ.html",srcName:"ImageJ User Guide「Working with ImageJ」",version:"User Guide 1.46r 時点の記述を含む一般原理。現行版でも解釈は同一である。",lessons:["L02","L18"],terms:["グレー値","Mean Gray Value","SNR"]}
]},
{id:"D3",title:"表示・LUT・色とチャンネル",intro:"表示の変更と画素値の変更は別物である。LUT、表示範囲、チャンネルとコンポジット画像の仕組みを区別して理解する。",entries:[
{id:"D3-1",title:"LUT（ルックアップテーブル）と疑似カラー",menu:"Image > Lookup Tables",body:["LUTは、グレー値と表示色（赤・緑・青の各成分）の対応表である。グレースケール画像にLUTを割り当てると、強度の違いが色の違いとして表示される疑似カラー画像になる。色は表示のための符号化であり、画素値そのものは単一チャンネルのままである。","LUTの変更は表示だけを変え、測定値には影響しない。逆に、疑似カラー表示をRGB画像として保存・変換すると、チャンネル分離した定量はできなくなる。"],points:["LUTはグレー値→表示色の対応表","LUT変更は表示のみで画素値は不変","定量は疑似カラー化する前のデータで行う"],caution:"カラフルな表示は強度分布の可視化には有効だが、色の印象で強度を判断しないこと。必ず数値とヒストグラムで確認する。",src:"https://imagej.github.io/imagej-wiki-static/User_Guide/Working_with_ImageJ.html",srcName:"ImageJ User Guide「Working with ImageJ」",version:"User Guide 1.46r 時点の記述。現行1.54系でもLUTの仕組みは同一である。",lessons:["L12"],terms:["LUT（ルックアップテーブル）","疑似カラー画像"]},
{id:"D3-2",title:"Brightness/Contrast は表示範囲の調整であって画素値の変更ではない",menu:"Image > Adjust > Brightness/Contrast...",body:["Brightness/Contrast は、ヒストグラムを見ながら、どのグレー値範囲を画面の黒〜白に対応づけるか（表示範囲）を調整する道具である。標準的な使い方では画素値そのものは書き換わらず、見た目だけが変わる。","ただし Apply を押すなど、表示範囲を画素値へ反映させる操作を行うと、その時点で値が書き換わり、範囲外の情報は失われる。表示の最適化と、値の変更は明確に区別すること。","ヒストグラム表示される Count / Mean / Mode / Min / Max は、選択範囲内の画素値の統計であり、表示範囲の変更では変わらない。"],points:["表示範囲の調整は画素値を変えない","Apply等の反映操作では値が書き換わる","統計量は表示ではなく実データから計算される"],caution:"「見やすくした」つもりで Apply して保存すると、元データの階調が失われる。解析用データでは反映操作を避けること。",src:"https://imagejdocu.list.lu/gui/analyze/histogramme",srcName:"ImageJ Documentation Wiki「Histogram」",version:"imagejdocu の現行記載に基づく。表示と値の区別は User Guide 1.46r 時代から一貫している。",lessons:["L12"],terms:["Brightness/Contrast","ヒストグラム","LUT（ルックアップテーブル）"]},
{id:"D3-3",title:"チャンネルとコンポジット画像",menu:"Image > Color > Merge Channels...",body:["コンポジット画像は、複数のチャンネルを分離したまま保持する画像形式である。各チャンネルは8/16/32-bitのいずれでもよく、3チャンネルを超える構成も可能で、チャンネルごとに表示のオン/オフやLUTを切り替えられる。","これに対して通常のRGB画像は、表示のためにチャンネルが1枚に固定された表現である。蛍光の多重染色のように、チャンネルごとの定量が必要なデータはコンポジットとして扱い、RGB化は表示・提出用に限るべきである。"],points:["コンポジットはチャンネルを分離保持する","各チャンネルは独立したビット深度を持てる","定量はコンポジットの各チャンネルで行う"],caution:"コンポジットをRGBへ変換するとチャンネル情報が混ざり、分離した測定はできなくなる。",src:"https://imagej.github.io/imagej-wiki-static/User_Guide/Working_with_ImageJ.html",srcName:"ImageJ User Guide「Working with ImageJ」",version:"User Guide 1.46r 時点の記述。現行版でもコンポジットの仕様は同一である。",lessons:["L04","L21"],terms:["コンポジット画像","チャンネル","ハイパースタック"]},
{id:"D3-4",title:"Split Channels と Merge Channels の使い分け",menu:"Image > Color > Split Channels / Merge Channels...",body:["Split Channels は、合成画像やRGB画像をチャンネルごとのグレースケール画像に分離する。分離後の各画像は独立に測定・処理できるため、チャンネル別定量の出発点になる。","Merge Channels は、開いているグレースケール画像を各チャンネルへ割り当てて合成画像を作る。Create Composite を選ぶとチャンネルを保持するコンポジット画像になり、表示の切り替えや後からの再分離が可能である。"],points:["Split＝分離して定量可能にする操作","Merge＋Create Composite＝チャンネル保持の合成","RGBへの焼き込みは表示用に限る"],caution:"割り当てを誤るとチャンネルの取り違えが起きる。合成後は各チャンネルのLUTと内容を必ず確認すること。",src:"https://imagej.net/mbf/colour_image_processi.htm",srcName:"MBF ImageJ Manual「Colour image processing」（imagej.net 収載）",version:"MBFマニュアル（imagej.net収載）の記載に基づく。現行版でも操作体系は同一である。",lessons:["L21"],terms:["Merge Channels","コンポジット画像","チャンネル"]}
]},
{id:"D4",title:"ROIと選択",intro:"ROI（関心領域）は測定と処理の対象を指定する仕組みである。マスク・オーバーレイとの違い、ROI Managerによる管理、保存と再利用を整理する。",entries:[
{id:"D4-1",title:"ROI・マスク・オーバーレイの違い",menu:"—（概念の区別）",body:["ROI（選択）は、画像上に一時的に指定された対象範囲であり、同時にアクティブにできるのは1つだけである。測定や処理はこのアクティブな選択に対して行われる。","マスクは、対象と背景を画素値（多くは0と255）で表した画像そのものであり、データとして保存・演算に使える。一方オーバーレイは、画素値を変えずに画像上へ重ねて表示されるROI等の要素で、複数を保持でき、非破壊的な注釈・確認に使う。","「どこを測るか」を決めるのがROI、「対象の画素集合」をデータ化したものがマスク、「見せ方」として重ねるのがオーバーレイ、と区別すると混乱が少ない。"],points:["ROI＝一時的な対象指定（同時には1つだけ）","マスク＝画素値で表された対象データ","オーバーレイ＝非破壊の重ね表示（複数保持可）"],caution:"ROIを描いただけでは画像データは変わらない。マスク化（Convert to Mask等）して初めて画素データになる。",src:"https://imagej.github.io/imagej-wiki-static/User_Guide/Working_with_ImageJ.html",srcName:"ImageJ User Guide「Working with ImageJ」",version:"User Guide 1.46r 時点の記述。現行1.54系でも三者の区別は同一である。",lessons:["L05","L10"],terms:["ROI","マスク","オーバーレイ"]},
{id:"D4-2",title:"ROI Manager：複数のROIを保持し、まとめて測る",menu:"Analyze > Tools > ROI Manager...",body:["ROI Manager は、作成した選択を一覧として保持し、追加・削除・計測・描画・保存を行うための道具である。Add（キー「t」）で現在の選択を登録し、Measure で登録済みの全ROIをまとめて測定できる。","スタックに対しては More > Multi Measure を使うと、全スライスに対して全ROIを一括測定し、結果表として得られる。時間変化や Z 方向の変化を追う測定の基盤になる。"],points:["Addで登録、Measureで一括測定","Multi Measureはスタック全スライス×全ROIの測定","登録順が結果表の行対応を決める"],caution:"登録漏れや順序の入れ替わりは、結果の取り違えに直結する。登録時に名前（ラベル）を付けて管理すること。",src:"https://imagejdocu.list.lu/gui/analyze/tools",srcName:"ImageJ Documentation Wiki「ROI Manager / Tools」",version:"imagejdocu の現行記載に基づく。基本操作は User Guide 1.46r 時代から継続している。",lessons:["L06","L18"],terms:["ROI Manager","Multi Measure","Results表"]},
{id:"D4-3",title:"選択は同時に1つだけ：位置合わせと復元の基本",menu:"Edit > Selection > Restore Selection",body:["ImageJで同時にアクティブにできる選択は1つだけである。矢印キーで1ピクセルずつ微調整（ナッジ）でき、位置の細かな合わせ込みが可能である。","消してしまった選択は Restore Selection で復元でき、別の画像へ選択を移すときにも使う。複数画像で同じ位置を測る場合は、ROI Managerへ登録しておく方法が確実である。"],points:["アクティブな選択は常に1つ","矢印キーで1ピクセル単位の調整","Restore Selectionで復元・転用が可能"],caution:"新しい選択を作ると前の選択は消える。残したい選択はその都度ROI Managerへ登録すること。",src:"https://imagej.github.io/imagej-wiki-static/User_Guide/Working_with_ImageJ.html",srcName:"ImageJ User Guide「Working with ImageJ」",version:"User Guide 1.46r 時点の記述。現行版でも選択の仕様は同一である。",lessons:["L05"],terms:["ROI","Restore Selection","ROI Manager"]},
{id:"D4-4",title:"ROIの保存と再利用（.roi と ROIセットZIP）",menu:"Analyze > Tools > ROI Manager... > Save...",body:["ROI Manager の Save では、単一のROIは .roi ファイルとして、複数のROIは ZIP アーカイブとして保存される。Open で読み戻せば、別のセッションや別の画像でも同じ選択集合を再現できる。","測定条件の再現性を担保するには、画像データだけでなく、ROIセットと測定設定（Set Scale / Set Measurements の内容）を一緒に保存しておくことが重要である。"],points:["単体は.roi、複数はZIPで保存","Openで別セッションでも復元可能","画像＋ROI＋測定設定をセットで保管する"],caution:"ROIの座標は画像の左上原点基準である。サイズの異なる画像へ適用すると位置がずれる。",src:"https://imagejdocu.list.lu/gui/analyze/tools",srcName:"ImageJ Documentation Wiki「ROI Manager / Tools」",version:"imagejdocu の現行記載に基づく。保存形式は現行版でも同一である。",lessons:["L06"],terms:[".roiファイル / ROIセットZIP","ROI Manager"]}
]}
,
{id:"D5",title:"測定とResults",intro:"Measureの値は、Set Scale（空間校正）と Set Measurements（記録項目）の設定に全面的に依存する。値の意味と、単位がおかしいときの切り分け、粒子数が合わないときの点検手順をまとめる。",entries:[
{id:"D5-1",title:"Mean Gray Valueとは：選択内のグレー値の平均",menu:"Analyze > Set Measurements... / Analyze > Measure",body:["Mean Gray Value（平均グレー値）は、選択範囲内のグレー値の合計をピクセル数で割った値である。蛍光画像では「その領域の平均的な信号強度」として使われるが、あくまで平均であり、総量ではない。","総量に相当する指標が必要な場合は、面積×平均（Integrated Density の考え方）を用いる。平均だけを比較すると、面積の異なる対象同士で総量の大小を取り違える。","なお、Mean が記録されるかどうかは Set Measurements の設定に依存する。結果表に項目が現れない場合は、まず記録項目の指定を確認すること。"],points:["Mean＝グレー値合計 ÷ ピクセル数（平均強度）","総量は面積×平均で評価する","記録の有無は Set Measurements で決まる"],caution:"RGB画像で測るMeanは輝度ベースの値であり、チャンネル別強度ではない。蛍光定量は分離したグレースケールで行うこと。",src:"https://imagej.net/ij/docs/menus/analyze.html",srcName:"ImageJ 公式ドキュメント「Analyze Menu」",version:"User Guide 1.46r 系の Analyze メニュー解説に基づく。Mean の定義は現行1.54系でも同一である。",lessons:["L08","L18"],terms:["Mean Gray Value","Set Measurements","Measure"]},
{id:"D5-2",title:"Set Scale：ピクセルを実寸へ校正する",menu:"Analyze > Set Scale...",body:["Set Scale は、ピクセル数と既知の距離（スケールバーや撮影条件から得た実長）の対応を登録する空間校正の手続きである。校正が済んだ画像では、Area や長さの測定結果がピクセル数ではなく校正単位（µm など）で報告される。","校正情報は画像ごとに保持され、TIFF/ZIP形式で保存した場合に保持される。通常形式の中で校正情報を保存できるのはこの形式に限られる点も重要である。","「Global」にすると、新しく開く画像にも同じ校正を適用する設定になる。倍率の異なる画像を扱う環境では、意図しない適用が誤差の原因になる。"],points:["校正済みなら結果は実寸単位で報告される","校正情報はTIFF/ZIP保存で保持される","Global設定は倍率違いの画像で誤差の元になる"],caution:"校正は撮影倍率・ビニング条件ごとに異なる。条件が変わるたびに校正し直すこと。",src:"https://imagej.net/ij/docs/menus/analyze.html",srcName:"ImageJ 公式ドキュメント「Analyze Menu」",version:"User Guide 1.46r 系の解説に基づく。校正の仕組みは現行版でも同一である。",lessons:["L07","L20"],terms:["Set Scale","Area","スケールバー"]},
{id:"D5-3",title:"測定単位がおかしいとき：点検の順序",menu:"Analyze > Set Scale... / Image > Properties...",body:["測定結果の単位や桁がおかしい場合、原因はほぼ次のいずれかにある。(1) Set Scale が未設定で結果がピクセル単位のまま、(2) 前の画像で設定した校正が Global 設定により別の倍率の画像へ適用されている、(3) 画素サイズの入力ミス（単位の取り違え、µm と mm の混同など）。","切り分けは、Image > Properties で現在の校正値を確認し、既知の長さ（スケールバー等）を実際に測って実寸と一致するか検証する順序で行う。校正が不要な測定（個数など）と、校正が前提の測定（面積・長さ）を区別することも重要である。","スケールバーを入れる作業は、この校正が正しく済んでいることが前提になる。校正がない状態のバーは実寸と対応しない。"],points:["原因の典型：未校正／Global の誤適用／単位入力ミス","Propertiesで校正値を確認し、既知長で検証する","個数は校正不要、面積・長さは校正が前提"],caution:"校正値を直したら、直す前に得た測定結果は破棄して測り直すこと。混在させると表の途中で単位が変わる。",src:"https://imagej.net/ij/docs/menus/analyze.html",srcName:"ImageJ 公式ドキュメント「Analyze Menu」",version:"User Guide 1.46r 系の解説に基づく切り分け手順。現行版でも校正の保持方法は同じである。",lessons:["L07","L20"],terms:["Set Scale","Area","スケールバー"]},
{id:"D5-4",title:"Set Measurements：記録される項目は事前に決まっている",menu:"Analyze > Set Measurements...",body:["Measure や Analyze Particles が Results 表へ記録する項目は、Set Measurements ダイアログで事前に指定されたものだけである。面積、平均グレー値、最小・最大、重心、面積率（Area Fraction）などがここで選ばれる。","「測ったはずの項目が表にない」場合は、測定の失敗ではなく記録項目の未指定であることが多い。逆に、不要な項目を多く指定すると表が読みにくくなるため、目的に応じた最小限の指定が望ましい。","面積率のように、閾値処理と組み合わせて初めて意味を持つ項目もある。項目の意味を理解してから指定すること。"],points:["記録項目は Set Measurements で事前指定する","項目が無い＝未指定のことが多い","目的に応じた項目だけを指定する"],caution:"同じ実験の一連の測定では記録項目を統一すること。途中で変えると表の列構成が変わり、比較が困難になる。",src:"https://imagej.net/ij/docs/menus/analyze.html",srcName:"ImageJ 公式ドキュメント「Analyze Menu」",version:"User Guide 1.46r 系の解説に基づく。現行版でも記録項目の仕組みは同一である。",lessons:["L08","L17"],terms:["Set Measurements","Measure","Results表"]},
{id:"D5-5",title:"Analyze Particlesで数が合わないとき：原因の切り分け",menu:"Analyze > Analyze Particles...",body:["Analyze Particles は、二値化または閾値処理された画像のオブジェクトを走査して数え、それぞれを計測するコマンドである。数が合わない場合の原因は、(1) 閾値の範囲が不適切で対象の取りこぼし・背景の誤検出がある、(2) Size の範囲指定で対象が除外されている、(3) 接触した粒子が分離されず1個として数えられている、(4) 画像端に触れた粒子の扱い（Exclude on Edges）の設定、のいずれかであることが多い。","切り分けは、二値化結果を元画像と重ねて目視で照合し、次に Size・Circularity の条件を緩めて数え直し、最後に Watershed 等の分離処理の要否を判断する順序が有効である。Summarize を有効にすると個数・合計面積・平均サイズ・面積率が Summary に集計される。","粒子解析は前提条件（二値化の品質）に結果が全面的に依存するコマンドであり、数を合わせにいくための安易な条件変更は、再現性を損なう。条件は記録し、固定して使うこと。"],points:["原因の典型：閾値／Size範囲／接触粒子の未分離／端の扱い","二値化結果と元画像の重ね合わせで照合する","条件は記録して固定し、場当たり的に変えない"],caution:"Summarize の面積率（%Area）も、閾値と Size 条件に依存する値である。条件を併記せずに数値だけを報告しないこと。",src:"https://imagej.net/ij/docs/menus/analyze.html",srcName:"ImageJ 公式ドキュメント「Analyze Menu」",version:"User Guide 1.46r 系の解説に基づく。現行1.54系でも粒子解析の前提と設定項目は同一である。",lessons:["L08","L16"],terms:["Analyze Particles","閾値処理（Threshold）","Watershed"]}
]},
{id:"D6",title:"閾値・二値化・形態学処理",intro:"閾値「設定」と画素値の「変換」は別の操作である。この区別、Dark/Black Background の取り違え、Watershed の適用限界など、誤解の多い領域を整理する。",entries:[
{id:"D6-1",title:"ThresholdとConvert to Maskの違い",menu:"Image > Adjust > Threshold... / Process > Binary > Convert to Mask",body:["Threshold は、強度の範囲を指定して「対象ピクセルと背景ピクセルをどう分けるか」という基準を定める操作である。閾値を設定しただけでは、画素値そのものは書き換わらない。表示上、範囲内のピクセルが赤く示されるのは指定の可視化である。","これに対して Convert to Mask は、現在の閾値設定に基づき、画像を白黒（0と255）のマスク画像へ実際に変換するコマンドである。画素値が書き換わるのはこの時点である。","同様に Process > Binary > Make Binary も二値化コマンドである。「設定済みの閾値があればそれを使い、未設定なら自動で決める」という閾値の扱いは Convert to Mask と共通で、両者の違いは閾値の決め方ではなく、主に結果の形式（マスクとして扱うかどうか）にある。"],points:["Threshold＝分ける基準の設定（画素値は不変）","Convert to Mask＝現在の閾値（未設定なら自動決定）でマスク化","Make Binary＝同じ閾値の扱いで画像を二値化"],caution:"閾値を合わせただけで「二値化した」と誤解すると、その後の処理がすべて閾値未適用の画像に対して行われる。",src:"https://imagejdocu.list.lu/gui/process/binary",srcName:"ImageJ Documentation Wiki「Binary」",version:"imagejdocu の現行記載に基づく。Round 1 監査で一次情報により確認済みの区別である。",lessons:["L09","L10"],terms:["閾値処理（Threshold）","Convert to Mask","Make Binary","マスク"]},
{id:"D6-2",title:"閾値を設定しても画素値が変わらない理由と、値が変わる操作",menu:"Image > Adjust > Threshold...",body:["Threshold ウィンドウでの調整は、あくまで「どの範囲を対象とみなすか」の指定であり、元画像のデータには触れない。したがって、閾値を設定した状態で Measure を行っても、それは元画像の値に対する測定であり、Analyze Particles のように閾値を参照するコマンドだけがこの指定を利用する。","画素値が実際に変わるのは、Threshold ウィンドウの Apply、二値化コマンド（Make Binary / Convert to Mask）の実行時である。どの操作で値が変わるかを意識することが、定量データの保全に直結する。"],points:["閾値指定はデータ非破壊の「指定」である","値が変わるのは Apply / 二値化コマンド実行時","閾値を参照するのは Analyze Particles 等の特定コマンド"],caution:"Apply 後の画像を保存すると元の階調は失われる。適用は複製画像で行うこと。",src:"https://imagejdocu.list.lu/gui/process/binary",srcName:"ImageJ Documentation Wiki「Binary」",version:"imagejdocu の現行記載に基づく。Round 1 監査で確認済みの内容である。",lessons:["L09","L10"],terms:["閾値処理（Threshold）","二値画像（バイナリ）"]},
{id:"D6-3",title:"Dark BackgroundとBlack Backgroundの違い",menu:"Image > Adjust > Threshold... / Process > Binary > Options...",body:["名前が似ているため混同されやすいが、この2つは別のダイアログの、別の意味を持つ設定である。Threshold ウィンドウの Dark Background は、暗い背景に対して明るい対象を切り分ける際の、閾値範囲の解釈（背景が暗いこと）を指定するものである。","一方、Process > Binary > Options の Black Background は、二値画像について「黒いピクセル側を背景として扱うか」を決める設定で、対象と背景のどちらとして画素を数えるかという、二値化後の解釈全体に影響する。","取り違えると、対象と背景が反転したまま解析が進み、面積率や個数がすべて逆転した結果になる。"],points:["Dark Background＝Threshold側、暗背景の解釈指定","Black Background＝Binary Options側、二値画像の対象/背景の解釈","反転ミスは面積率・個数の全反転につながる"],caution:"二値化結果が意図と反転していたら、まずこの2設定を確認すること。Round 1 監査でも混同注意として確認された項目である。",src:"https://imagejdocu.list.lu/gui/process/binary",srcName:"ImageJ Documentation Wiki「Binary」",version:"imagejdocu の現行記載に基づく。設定の所在と意味は現行版でも同一である。",lessons:["L09","L10"],terms:["Black Background","閾値処理（Threshold）","二値画像（バイナリ）"]},
{id:"D6-4",title:"自動閾値とOtsu法：手法の前提を理解する",menu:"Image > Adjust > Threshold...（Method の選択）",body:["自動閾値の手法には Default（IsoData系）、Otsu、Huang、Li、MaxEntropy、Triangle など多数があり、それぞれ「何を最適とみなすか」の前提が異なる。万能な手法はなく、ヒストグラムの形状に合った選択が必要である。","代表的な Otsu 法は、閾値で分けた2クラスのクラス内分散が最小（＝クラス間分散が最大）になる閾値を選ぶ。対象と背景が明確に分かれた二峰性のヒストグラムに向くが、対象が極端に小さい場合や背景が不均一な場合は適切な閾値にならないことがある。","どの手法を使ったかは結果を左右する条件であり、手法名と対象画像の前処理を記録することが再現性の前提になる。"],points:["手法ごとに最適化の前提が異なる","Otsuは二峰性ヒストグラム向き","手法名と前処理を記録する"],caution:"自動閾値の結果を無検証で採用しないこと。元画像との重ね合わせで妥当性を必ず確認する。",src:"https://imagejdocu.list.lu/gui/process/binary",srcName:"ImageJ Documentation Wiki「Binary」および自動閾値手法の解説",version:"imagejdocu 現行記載に基づく。手法一覧は現行版の Threshold ダイアログと対応する。",lessons:["L09"],terms:["Otsu法","閾値処理（Threshold）","ヒストグラム"]},
{id:"D6-5",title:"Watershedが不適切な場合",menu:"Process > Binary > Watershed",body:["Watershed は、距離マップとその極大点をもとに、接触した粒子同士の境界を推定して分離する処理である。滑らかで凸形状に近く、重なりの少ない粒子の分離には有効である。","一方、形状が不規則で凹凸の多い対象、内部に窪みのある対象、大きく重なり合った対象では、窪みごとに過分割したり、誤った位置で切断したりする。距離マップの極大点が対象1つに対して複数現れる形状では、原理的に過分割が避けられない。","分離結果は必ず元画像と照合し、過分割・未分離の傾向を確認すること。形状が複雑な対象では、Watershed に頼らず、閾値や前処理の改善、あるいは面積ベースの集計への切り替えを検討すべきである。"],points:["原理：距離マップの極大点から境界を引く","凹凸・重なりの大きい対象では過分割・誤切断が起きる","分離結果は元画像との照合が必須"],caution:"過分割された数は「数えられた個数」としてそのまま報告できない。分離の成否は画像ごとに判断すること。",src:"https://imagejdocu.list.lu/gui/process/binary",srcName:"ImageJ Documentation Wiki「Binary」",version:"imagejdocu の現行記載に基づく。適用限界は Round 2 の GPT 監査指摘を一次情報で確認のうえ収録した。",lessons:["L16"],terms:["Watershed","距離マップ","Analyze Particles"]},
{id:"D6-6",title:"形態学処理（モルフォロジー演算）の基礎：Erode / Dilate / Open / Close",menu:"Process > Binary > Erode / Dilate / Open / Close",body:["形態学処理は、二値画像の形状に対して行う演算の総称である。Erode（侵食）は対象を一回り小さくし、小さな突起や細い連結を取り除く。Dilate（膨張）は対象を一回り大きくし、小さな欠けを埋める。","Open は侵食→膨張の組み合わせで、小さなノイズ状の対象を取り除きつつ大きな対象の形を概ね保つ。Close は膨張→侵食で、対象内部の小さな穴や切れ目を埋める。","これらは形状を変える処理であり、面積や個数の測定前に適用すると結果も変わる。適用の有無と回数は、測定条件として記録しなければならない。"],points:["Erode＝縮小、Dilate＝拡大が基本演算","Open＝小ノイズ除去、Close＝穴・切れ目埋め","形状変更は測定値に直接影響する"],caution:"見た目を整えるための形態学処理は、定量値の改変でもある。解析前の適用は目的と根拠を明示すること。",src:"https://imagejdocu.list.lu/gui/process/binary",srcName:"ImageJ Documentation Wiki「Binary」",version:"imagejdocu の現行記載に基づく。各演算の定義は現行版でも同一である。",lessons:["L10","L16"],terms:["モルフォロジー演算","二値画像（バイナリ）"]}
]},
{id:"D7",title:"フィルタと画像演算",intro:"フィルタは「近傍の値から新しい値を計算する」処理であり、常に見た目と引き換えに情報を変える。各フィルタの原理と副作用、演算時の型の問題を整理する。",entries:[
{id:"D7-1",title:"平滑化フィルタの原理と副作用：Smooth / Mean / Gaussian Blur",menu:"Process > Smooth / Process > Filters > Mean... / Gaussian Blur...",body:["平滑化は、各ピクセルを近傍の平均的な値で置き換え、細かな変動（ノイズ）を抑える処理である。Smooth は3×3近傍の平均、Mean フィルタは Radius で指定した近傍の平均、Gaussian Blur はガウス関数で重み付けした平均（畳み込み）で、Sigma はガウス関数の標準偏差σを表す。","副作用として、エッジは鈍り、細い構造は周囲に溶け込み、ピークの最大値は下がる。強度を定量する画像では、平滑化の適用がそのまま測定値の変化になる。","ノイズ低減の効果と情報の損失は表裏一体であり、「きれいに見える」ことは「正しく測れる」ことと同義ではない。定量前の平滑化は、必要性とパラメータを明示して行うこと。"],points:["平滑化＝近傍の平均化、Gaussianは重み付き平均","副作用：エッジの鈍化、ピーク値の低下、細構造の消失","定量値そのものが変わる処理である"],caution:"取得条件の異なる画像に同じ見た目を求めて平滑化を変えると、比較可能性が失われる。条件は統一すること。",src:"https://imagejdocu.list.lu/gui/process/filters",srcName:"ImageJ Documentation Wiki「Filters」",version:"imagejdocu の現行記載に基づく。Gaussian の Sigma の定義は User Guide（Process Menu）でも確認済みである。",lessons:["L11"],terms:["Gaussian Blur","Meanフィルタ","Smooth","SNR"]},
{id:"D7-2",title:"Medianフィルタ：平均ではなく中央値で置き換える",menu:"Process > Filters > Median...",body:["Median フィルタは、各ピクセルを近傍の値の中央値で置き換える。平均と違い、外れ値（飛び値）の影響を受けにくいため、孤立した極端に明るい/暗い点（塩胡椒状ノイズ）の除去に向く。","エッジの保存性も平均系より高いが、近傍（Radius）を大きくすると細い線状構造が消えるなどの副作用がある。対象の大きさに対して十分小さい Radius を選ぶことが原則である。"],points:["中央値置換のため飛び値に強い","塩胡椒状ノイズの除去向き","Radiusが大きいと細構造が消える"],caution:"中央値もまた画素値の書き換えである。定量画像への適用は、平滑化と同様に値の変化を伴う点を意識すること。",src:"https://imagejdocu.list.lu/gui/process/filters",srcName:"ImageJ Documentation Wiki「Filters」",version:"imagejdocu の現行記載に基づく。定義は現行版でも同一である。",lessons:["L11"],terms:["Medianフィルタ","Gaussian Blur"]},
{id:"D7-3",title:"Unsharp Mask：ぼかしたコピーを差し引いてエッジを強調する",menu:"Process > Filters > Unsharp Mask...",body:["Unsharp Mask は、元の画像から「Gaussian Blur でぼかしたコピー」を差し引くことで、エッジや細部を強調するフィルタである。パラメータは、Radius＝差し引くぼかしのσ、Mask Weight＝差し引きの強さ（フィルタ強度）を表す。","Mask Weight を大きくしすぎると、エッジの周囲に過強調の縁（ハロー）が現れ、ピーク値は実物以上に跳ね上がる。強調された画像は観察には有用でも、強度の定量には使えない。","似た名前の Sharpen（3×3の重み付き平均による強調）とは別の処理であり、パラメータの意味も異なる。"],points:["原理：原画像 − ぼかしたコピー でエッジ強調","Radius＝ぼかしのσ、Mask Weight＝強さ","過強調ではハローとピーク値の増大が起きる"],caution:"強調処理後の画像で強度を測らないこと。定量は未加工データで行い、強調は表示・観察用に限る。",src:"https://imagej.net/ij/docs/guide/146-29.html",srcName:"ImageJ User Guide「Process Menu」（29章）",version:"User Guide 1.46r の Process Menu 解説に基づく。パラメータの意味は現行版でも同一である。",lessons:["L11"],terms:["Unsharp Mask","Sharpen","Gaussian Blur"]},
{id:"D7-4",title:"Gamma補正：式と適用範囲",menu:"Process > Math > Gamma...",body:["Gamma 補正は、画素値にべき乗を適用する階調変換である。8-bit画像では f(p) = (p/255)^gamma × 255 の形で計算され、gamma の指定範囲は 0.05〜5.0 である。gamma が1より小さいと中間調が持ち上がり、大きいと沈む。","適用範囲に注意が必要で、16-bit画像では画像の最小値・最大値でスケーリングしてから同じ考え方を適用する。つまり同じ gamma 値でも、画像の値域によって結果の対応は異なる。","Gamma は非線形変換であり、強度の比例関係を崩す。表示の調整として使う分には問題ないが、補正後の画像で強度比を論じることはできない。"],points:["8-bitでは (p/255)^gamma×255、範囲0.05〜5.0","16-bitでは最小・最大でスケーリングして適用","非線形変換のため強度比が崩れる"],caution:"定量解析に Gamma 補正後の画像を使わないこと。Round 1 監査で適用範囲の明記が必要と確認された項目である。",src:"https://imagejdocu.list.lu/gui/process/math",srcName:"ImageJ Documentation Wiki「Math」",version:"imagejdocu の現行記載に基づく。式と範囲は Round 1 で一次情報により確認済みである。",lessons:["L13"],terms:["Gamma","Math（Process > Math）"]},
{id:"D7-5",title:"Image Calculator と 32-bit Result：演算で値を潰さない",menu:"Process > Image Calculator...",body:["Image Calculator は、2枚の画像の間で加減乗除や論理演算（AND など13種の演算子）を行うコマンドである。差分画像の作成、背景画像の引き算、マスクによる共通部分の抽出などに使う。","重要なのは結果の型である。「32-bit Result」を指定すると、結果は浮動小数で保持され、負の値や小数、範囲外の値も潰れない。指定しない場合、整数型の範囲に丸められ、差分が負になる部分などが失われる。標準設定ではゼロ除算の結果は Infinity や NaN として現れる。","演算はピクセル位置が完全に対応していることが前提であり、サイズや位置のずれた画像同士の演算は意味を持たない。"],points:["2画像間の算術・論理演算（13演算子）","32-bit Resultで負値・小数を保持できる","位置合わせが演算の前提条件"],caution:"整数型のまま差分を取ると負の差分が0に潰れ、変化を過小評価する。差分・除算系は32-bit結果を原則とすること。",src:"https://imagejdocu.list.lu/gui/process/image_calculator",srcName:"ImageJ Documentation Wiki「Image Calculator」",version:"imagejdocu の現行記載に基づく。ゼロ除算の扱いは「標準設定では」という留保付きで Round 1 に確認済みである。",lessons:["L13"],terms:["Image Calculator","Infinity / NaN","AND演算（画像）","背景差し引き"]}
]},
{id:"D8",title:"背景補正",intro:"背景補正は「信号を取り出す」処理であると同時に「信号を変える」処理でもある。Subtract Background の仕組み、ローリングボール半径の決め方、補正で値が変わる理由を整理する。",entries:[
{id:"D8-1",title:"Subtract Background とローリングボールの考え方",menu:"Process > Subtract Background...",body:["Subtract Background は、ピクセル値を高さとみた曲面の裏側をボールが転がる軌跡として「滑らかな背景」を推定し、それを差し引いて背景を均すコマンドである。照明ムラのある画像で、場所によって閾値や強度がずれる問題への前処理として使う。","Rolling Ball Radius は背景推定のスケールを決める。目安は画像の種類で異なり、8-bitやRGBでは「背景ではない最大の対象の半径」以上の大きさに取るのが原則である。画素値の範囲が大きく異なる画像では、半径は値の範囲に反比例する方向へ調整し、16-bit画像（画素値0〜65535）では0.2〜5程度が典型値とされる。","明るい背景に暗い対象がある画像では Light Background を指定する。Sliding Paraboloid を選ぶと、ボールではなく放物面で背景を近似する方式に切り替わる。"],points:["背景を推定して差し引く前処理","半径の目安は型で異なる（8-bit/RGB：最大対象の半径以上）","明背景＋暗対象では Light Background"],caution:"対象より小さい半径では、対象自体が背景として差し引かれてしまう。Preview で対象が消えていないか確認すること。",src:"https://imagejdocu.list.lu/gui/process/subtract_background",srcName:"ImageJ Documentation Wiki「Subtract Background」",version:"imagejdocu の現行記載に基づく。半径の適用範囲は Round 2 監査で一次情報により確認・修正済みの内容である。",lessons:["L19"],terms:["Subtract Background","ローリングボール半径"]},
{id:"D8-2",title:"背景補正で信号が変わる理由",menu:"Process > Subtract Background...（適用時の注意）",body:["背景補正は、測定したい信号そのものではなく「信号＋背景」の合計から、推定した背景分を差し引く操作である。推定背景には、真の背景だけでなく、対象の裾野や広がった成分まで含まれることがあるため、補正後のピーク値や積算値は補正前と変わる。","特に、対象より小さい半径や不適切な方式では、対象の信号成分まで差し引かれ、強度が系統的に過小になる。逆に背景の推定が不十分だと、場所によるバラつきが残る。","したがって背景補正は「値の正しさ」を自動で保証する処理ではなく、補正のパラメータ自体が測定条件の一部である。画像間で比較する場合は、同一の補正条件を全画像に適用し、条件を記録することが必須になる。"],points:["引かれるのは推定背景で、対象の裾野も含まれ得る","パラメータ不適では信号まで差し引かれる","比較する全画像で同一条件を適用し記録する"],caution:"補正前後の値を混ぜて比較しないこと。補正は全データに一貫して適用するか、しないかを統一する。",src:"https://imagejdocu.list.lu/gui/process/subtract_background",srcName:"ImageJ Documentation Wiki「Subtract Background」",version:"imagejdocu の現行記載（背景推定の仕組み）に基づく独自解説。原理の説明として現行版でも有効である。",lessons:["L19","L18"],terms:["Subtract Background","背景差し引き","Mean Gray Value"]},
{id:"D8-3",title:"背景ROIによる補正：対象の平均から背景の平均を引く",menu:"Analyze > Tools > ROI Manager... / Analyze > Measure",body:["蛍光強度の評価では、対象ROIと背景ROI（対象のない領域）を ROI Manager に登録し、それぞれ Measure して、対象の Mean から背景の Mean を差し引く方法が基本になる。これは「平均強度」の補正であり、総量の補正とは区別すること。","背景ROIの置き方（場所・大きさ・個数）で結果は変わるため、選び方のルールを決めて全画像で統一する。撮影条件や前処理の条件が異なる画像同士では、この補正をしても比較可能性は回復しない。","スタック全体に同じROI群で適用する場合は Multi Measure が使える。"],points:["補正＝対象Mean − 背景Mean（平均強度の補正）","背景ROIの選び方をルール化し統一する","取得条件の異なる画像は補正しても比較できない"],caution:"背景ROIを対象のすぐ近くに置くと、対象の広がった信号まで背景として引いてしまう。置き方の根拠を記録すること。",src:"https://imagejdocu.list.lu/gui/analyze/tools",srcName:"ImageJ Documentation Wiki「ROI Manager / Tools」",version:"imagejdocu の現行記載に基づく。Round 2 監査で妥当性を確認済みの方法である。",lessons:["L18"],terms:["ROI Manager","Mean Gray Value","Multi Measure"]}
]}
,
{id:"D9",title:"スタックとZ投影",intro:"スタックは「同サイズ・同深度の画像の束」、ハイパースタックはそれにチャンネルと時間の軸を加えたもの。Z投影の方式選択と、スタック測定の基本を整理する。",entries:[
{id:"D9-1",title:"スタックとハイパースタックの構造",menu:"Image > Stacks / Image > Hyperstacks",body:["スタックは、複数の画像（スライス）を1つのウィンドウにまとめたもので、全スライスが同じサイズ・同じビット深度であることが前提になる。Z方向（深さ）の断層像の並びとして扱うのが典型である。","ハイパースタックはスタックの拡張で、x・y に加えて z（深さ）、c（チャンネル）、t（時間）の軸を持つ4D/5Dデータを扱う。軸の取り違え（チャンネルと時間の混同など）は、解析全体の誤りの元になる。","メモリに収まらない画像列は仮想スタックとして開けるが、ディスク常駐のため読み取り専用であり、処理の適用には制限がある。"],points:["スタックは全スライス同サイズ・同深度が前提","ハイパースタックは z・c・t の軸を持つ","仮想スタックは読み取り専用"],caution:"読み込む際に軸の割り当てを確認すること。c と t の取り違えは、見た目では気づきにくい。",src:"https://imagej.github.io/imagej-wiki-static/User_Guide/Working_with_ImageJ.html",srcName:"ImageJ User Guide「Working with ImageJ」",version:"User Guide 1.46r 時点の記述。現行1.54系でもスタックの構造は同一である。",lessons:["L04"],terms:["スタック","ハイパースタック","仮想スタック","スライス","ボクセル"]},
{id:"D9-2",title:"Z投影の方式は「何を見たいか」で選ぶ",menu:"Image > Stacks > Z Project...",body:["Z Project は、スタックを Z 方向に投影して1枚の画像にまとめる処理で、方式は Average Intensity（平均）、Maximum Intensity（最大）、Minimum Intensity（最小）、Sum Slices（合計）、Standard Deviation（標準偏差）、Median（中央値）の6種がある。","蛍光の構造を際立たせたい場合は Maximum、ノイズを抑えて平均的な分布を見たい場合は Average、総量に比例する指標が欲しい場合は Sum が候補になる。方式によって画素値の意味がまったく異なるため、「投影した」という事実だけでなく方式名を記録することが必須である。","開始・終了スライスを指定して、一部の範囲だけを投影することもできる。範囲の指定も結果を左右する条件である。"],points:["方式は6種：平均／最大／最小／合計／標準偏差／中央値","方式で画素値の意味が変わるため記録が必須","投影範囲（開始・終了スライス）も条件の一部"],caution:"Maximum投影はノイズの最大値も拾う。定量に使う場合は、方式の選択根拠を明示すること。",src:"https://imagej.net/imaging/z-functions",srcName:"imagej.net「Z-functions」解説",version:"imagej.net の現行解説に基づく。方式が6種であることは Round 2 監査でも実装と照合して確認済みである（旧 User Guide 本文には5方式と読める記述が残る）。",lessons:["L22"],terms:["Z投影","スタック"]},
{id:"D9-3",title:"Multi Measure：スタックの全スライスを同じROI群で測る",menu:"Analyze > Tools > ROI Manager... > More > Multi Measure",body:["Multi Measure は、ROI Manager に登録した全ROIを、スタックの全スライスに対して一括測定し、結果表として出力する機能である。時間経過や Z 方向の各位置での強度変化を、同じ領域定義で追跡できる。","結果の並び（1スライスにつき全ROI分を1行にするか等）は出力形式の設定で変わる。解析ソフトへ渡す前に、行と ROI・スライスの対応を小さなデータで確認しておくことが安全である。"],points:["全スライス×全ROIの一括測定","出力形式で行の対応が変わる","本番前に小データで対応関係を確認する"],caution:"ROIの登録順やスライス範囲を途中で変えると、行の対応がずれ、時系列の取り違えが起きる。",src:"https://imagejdocu.list.lu/gui/analyze/tools",srcName:"ImageJ Documentation Wiki「ROI Manager / Tools」",version:"imagejdocu の現行記載に基づく。現行版でも Multi Measure の仕様は同一である。",lessons:["L06","L18"],terms:["Multi Measure","ROI Manager","スタック"]},
{id:"D9-4",title:"仮想スタックの制約：開けることと処理できることは別",menu:"File > Import > Image Sequence...（仮想スタックとして開く）",body:["仮想スタックは、画像データをメモリではなくディスク上に置くスタックで、メモリに収まらない大きな画像列を開いて閲覧できる。代償として読み取り専用であり、画素値を書き換える処理は適用できない。","大きなデータの確認・測定対象の選定には有効だが、フィルタや変換などの処理が必要な場合は、対象を絞って通常のスタックとして読み込み直す運用になる。"],points:["ディスク常駐で大容量を開ける","読み取り専用のため画素の書き換え不可","処理が必要なら範囲を絞って再読込する"],caution:"「開けた」ことをもって「解析できる」と判断しないこと。処理可否は事前に小さな範囲で試す。",src:"https://imagej.github.io/imagej-wiki-static/User_Guide/Working_with_ImageJ.html",srcName:"ImageJ User Guide「Working with ImageJ」",version:"User Guide 1.46r 時点の記述。現行版でも仮想スタックは読み取り専用である。",lessons:["L04"],terms:["仮想スタック","スタック"]}
]},
{id:"D10",title:"マクロとバッチ処理",intro:"マクロは「手作業の手順を再現可能な記録に変える」仕組みである。Recorderによる作成、バッチモードによる高速化、フォルダ一括処理と出力の注意点を整理する。",entries:[
{id:"D10-1",title:"マクロの基本：run() でコマンドを実行する",menu:"Plugins > Macros > Record... / Run",body:["ImageJマクロは Java に似たマクロ言語で書かれたテキスト（.ijm 等）であり、中心となるのは run() 関数で、400を超えるメニューコマンドをパラメータ付きで実行できる。コマンドレコーダは GUI 操作から run() 呼び出しを生成するため、手作業の手順をそのままマクロ化の出発点にできる。","setThreshold() や getTitle() のような組み込み関数により、閾値の設定やアクティブ画像の取得といった操作も記述できる。マクロ化の価値は高速化だけでなく、手順と条件をテキストとして保存し、再現・共有できることにある。"],points:["run() で400超のコマンドを実行可能","Recorderが手作業からコードを生成する","手順と条件がテキストとして残る＝再現性の担保"],caution:"記録されたマクロには、その時点の画像名や条件が固定値として含まれることがある。別データへの適用前に確認すること。",src:"https://imagej.net/ij/developer/macro/functions.html",srcName:"ImageJ公式「Macro Functions」リファレンス",version:"現行の imagej.net 掲載リファレンスに基づく。マクロ言語の基本体系は1.46r時代から継続している。",lessons:["L14"],terms:[".ijm / マクロファイル","コマンドレコーダ"]},
{id:"D10-2",title:"setBatchMode：表示を止めて高速化する",menu:"（マクロ関数 setBatchMode）",body:["setBatchMode(true) でバッチモードに入ると、マクロ実行中に画像を表示しなくなり、処理が大幅に高速化される。バッチモードはマクロ終了時に自動的に解除される。","ただし、表示されない状態では「どの画像が対象になっているか」の視認確認ができない。対象画像の指定ミスがそのまま結果になるため、バッチ化する前に、表示ありの状態で同じ手順を通し、結果を確認しておくことが前提になる。"],points:["バッチモードは表示を省略して高速化する","終了時に自動解除される","バッチ化の前に表示ありで全手順を検証する"],caution:"過去資料には高速化の倍率の記載もあるが、倍率は環境・処理内容で変わるため、数値を根拠に設計しないこと。",src:"https://imagej.net/ij/developer/macro/functions.html",srcName:"ImageJ Macro Language 公式リファレンス（PDF）",version:"公式マクロ言語リファレンスに基づく。高速化の具体的倍率はバージョン・環境依存のため本リファレンスでは数値を採用していない。",lessons:["L14","L15"],terms:["バッチ処理"]},
{id:"D10-3",title:"Batch Macro：出力フォルダを指定しないと自動保存されない",menu:"Process > Batch > Macro...",body:["Process > Batch > Macro は、入力フォルダ内の各画像を自動で開き、指定したマクロを適用し、出力フォルダへ保存して閉じる流れを繰り返す仕組みである。","重要な注意点として、出力（Output）フォルダを指定しない場合、バッチ機能による処理結果の自動保存は行われない（マクロの中に保存処理を明示的に書いた場合は、その限りではない）。「処理は回ったのに結果が残っていない」という事故はこの仕様による。","出力は入力と別のフォルダを指定し、同名の出力があると上書きされることがあるため、元画像のバックアップを残しておくこと。本番適用の前に、少数枚の別フォルダで試して結果を確認するのが安全である。"],points:["入力→マクロ適用→出力へ保存→閉じる、の反復","Output未指定では自動保存されない","出力は入力と別フォルダにし、元画像を残す"],caution:"サブフォルダは標準では再帰処理されない。階層構造のデータは構成を確認してから適用すること。",src:"https://imagej.github.io/imagej-wiki-static/Batch_mode.html",srcName:"ImageJ公式「Batch Mode / Batch Processing」解説",version:"公式 Batch Processing 解説に基づく。自動保存の仕様は Round 2 監査で公式文書により確認済みである。",lessons:["L23"],terms:["バッチマクロ（Process > Batch）","バッチ処理"]},
{id:"D10-4",title:"コマンドライン実行と getArgument()：外部から条件を渡す",menu:"（コマンドライン -macro / -batch オプション）",body:["ImageJはコマンドラインの -macro / -batch オプションでマクロを指定して起動でき、渡した文字列引数をマクロ側で getArgument() により取得できる。これにより、対象フォルダや条件を外部から変えながら同じマクロを繰り返し実行する運用が可能になる。","人手の介在しない実行では、エラー時の見落としが起きやすい。出力ファイル数や代表画像の結果など、実行後の機械的な確認項目を決めておくことが重要である。"],points:["-macro / -batch で無人実行が可能","getArgument() で外部条件を受け取る","実行後は出力件数などで機械的に確認する"],caution:"無人実行では途中エラーが画面に残らない場合がある。ログや出力の確認を省略しないこと。",src:"https://imagej.net/ij/developer/macro/macros.html",srcName:"ImageJ公式「Macros」解説",version:"公式 Macros 解説に基づく。オプション体系は現行版でも継続している。",lessons:["L15"],terms:["バッチ処理"]}
]},
{id:"D11",title:"プラグインと拡張",intro:"ImageJの標準コマンド自体が内部プラグインとして実装されており、拡張の仕組みは本体と地続きである。プラグインの配置、Fijiの更新管理、Bio-Formatsによる形式対応を整理する。",entries:[
{id:"D11-1",title:"プラグインの仕組み：pluginsフォルダに入れるとメニューに載る",menu:"Plugins メニュー",body:["プラグインは Java で書かれ .class にコンパイルされた拡張モジュールであり、plugins フォルダ（サブフォルダを含む）へ配置すると、再起動後に Plugins メニューへ載る。ファイル名にはアンダースコアを含むことなど、メニューへ載るための命名の条件がある。","ImageJの標準コマンドの多くも ij.jar の内部にプラグインとして実装されており、「本体機能」と「プラグイン」の境界は実装上は連続している。そのため、バージョンや追加プラグインの違いが、そのまま使える機能の違いになる。"],points:["Java製モジュールを plugins フォルダへ配置","命名条件を満たすとメニューに自動で載る","標準コマンドも内部プラグインとして実装"],caution:"出典の不明なプラグインは、処理内容を検証できない限り定量解析には使わないこと。バージョンを記録しておくことも重要である。",src:"https://imagej.net/ij/docs/menus/plugins.html",srcName:"ImageJ公式「Plugins Menu」解説",version:"現行の imagej.net 掲載解説に基づく。命名条件は Round 1 監査で公式ページにより確認済みである。",lessons:["L15"],terms:["プラグイン","ij.jar","StartupMacros"]},
{id:"D11-2",title:"FijiのUpdaterと更新サイト：追加機能の入手と管理",menu:"Help > Update...",body:["Fijiでは ImageJ Updater が、更新サイト（Update Site）と呼ばれる配布元を登録・管理し、プラグイン一式の入手と更新を行う。Bio-Formats のような主要コンポーネントの更新も、Fijiでは Updater 経由が推奨される経路である。","更新サイトを追加すると、そのサイトが配布するコマンドがメニューに加わる。利便性と引き換えに、環境ごとに機能構成が変わるため、解析手順の共有時には「どの更新サイトを有効にしているか」も条件の一部として記録すべきである。"],points:["Updaterが更新サイト単位でプラグインを管理","Bio-Formats等の更新もFijiではUpdater経由","有効な更新サイトは解析条件の一部"],caution:"更新により既存手順の挙動が変わることがある。重要な解析の途中での一括更新は避け、更新後に代表データで再検証すること。",src:"https://imagej.net/formats/bio-formats",srcName:"imagej.net「Bio-Formats」解説",version:"imagej.net の現行解説に基づく。Updater の仕組みはFijiの現行配布でも継続している。",lessons:["L15"],terms:["ImageJ Updater","更新サイト（Update Site）","Bio-Formats"]},
{id:"D11-3",title:"Bio-Formats：メーカー形式とメタデータを読み込む",menu:"File > Import > Bio-Formats...",body:["Bio-Formats は、多数のライフサイエンス画像形式を読み書きするためのライブラリ／プラグイン群であり、Bio-Formats Importer を使うことで、各メーカー形式の画像と取得メタデータを、OMEモデルに標準化した形で読み込める。Fijiでは File > Open 系の操作に統合されている。","顕微鏡画像の画素サイズ・チャンネル構成・撮影条件といったメタデータは、空間校正や定量の前提になる。標準の開き方でこれらが欠落する形式では、Bio-Formats 経由の読み込みが正確な解析の前提条件になる。"],points:["多数のメーカー形式＋メタデータに対応","メタデータはOMEモデルに標準化される","校正情報の保持が定量の前提になる"],caution:"読み込み時のオプション（チャンネルの統合・分割等）でデータの形が変わる。選択したオプションを記録すること。",src:"https://imagej.net/formats/bio-formats",srcName:"imagej.net「Bio-Formats」解説",version:"imagej.net の現行解説に基づく。Fijiでは標準同梱コンポーネントとして提供される。",lessons:["L03","L15"],terms:["Bio-Formats","TIFF"]}
]},
{id:"D12",title:"ファイル形式とメタデータ",intro:"保存形式の選択は、データの保持範囲を決める行為である。TIFFが標準である理由、JPEGが定量に不向きな理由、保存で失われる情報を整理する。",entries:[
{id:"D12-1",title:"TIFFがImageJの標準形式である理由",menu:"File > Save As > Tiff...",body:["TIFFはImageJのデフォルト形式であり、8/16/32-bitおよびRGBに対応し、スケール（空間校正）などのメタデータを保存できる。通常形式の中で、校正情報を保存できるのはTIFF（およびZIP圧縮TIFF）に限られる。","解析の途中経過や結果画像を保存する形式としてTIFFが標準になるのは、可逆であることと、測定の前提情報（校正）を一緒に保持できることによる。"],points:["8/16/32-bit・RGBに対応する可逆形式","校正情報を保存できる通常形式はTIFF/ZIPのみ","解析データの保存はTIFFを標準とする"],caution:"表示用に別形式へ書き出した場合、校正情報は失われる。提出用ファイルと解析用ファイルは区別して管理すること。",src:"https://imagej.github.io/imagej-wiki-static/User_Guide/Working_with_ImageJ.html",srcName:"ImageJ User Guide「Working with ImageJ」",version:"User Guide 1.46r 時点の記述。現行1.54系でもTIFFがデフォルトであり、校正の保存範囲は同一である。",lessons:["L03"],terms:["TIFF","Set Scale"]},
{id:"D12-2",title:"JPEGが定量解析に不向きな理由",menu:"File > Save As > Jpeg...",body:["JPEGは非可逆圧縮の形式であり、保存のたびに画素値が近似値へ書き換わる。ブロック境界のノイズ（アーティファクト）が生じ、元のグレー値は復元できない。ImageJがネイティブに扱える形式にはTIFF・GIF・JPEG・PNG・DICOM・BMP・PGM・FITSがあるが、「開ける」ことと「定量に使える」ことは別である。","観察記録や共有には問題なくても、強度や面積を測る元データとしてJPEG保存された画像を使うべきではない。取得段階で可逆形式（TIFF等）を選ぶことが前提になる。"],points:["JPEGは非可逆で画素値が変わる","圧縮アーティファクトが測定誤差になる","元データは可逆形式で取得・保存する"],caution:"JPEGで受け取った画像しかない場合、その制約を結果の解釈に明記すること。数値の厳密な比較はできない前提で扱う。",src:"https://imagej.github.io/imagej-wiki-static/User_Guide/Working_with_ImageJ.html",srcName:"ImageJ User Guide「Working with ImageJ」",version:"User Guide 1.46r 時点の記述。現行版でもJPEGの非可逆性は変わらない。",lessons:["L03"],terms:["TIFF","グレー値"]},
{id:"D12-3",title:"メタデータと校正情報：保存で保持されるもの・されないもの",menu:"Image > Properties... / File > Save As",body:["ImageJ標準の保存では、保持されるメタデータの範囲は形式に依存する。代表的には、空間校正（スケール）はTIFF/ZIP形式でのみ保存され、それ以外の通常形式では保持されない。","また、表示に使っているLUTや表示範囲のような「見せ方」の情報と、測定の前提になる「校正」の情報は性質が異なる。後者が失われると、同じ画像でも測定結果の単位が変わってしまう。","メタデータ保持についての記述は「ImageJ標準の保存では」という留保のもとで理解すべきであり、Bio-Formats等の拡張経由の保存では範囲が異なり得る。"],points:["校正情報の保存はTIFF/ZIPに限られる（標準保存）","表示情報と校正情報は性質が異なる","拡張経由の保存では保持範囲が変わり得る"],caution:"形式変換のたびに、校正が保持されているか Properties で確認すること。Round 1 監査で留保の明記が必要と確認された項目である。",src:"https://imagej.github.io/imagej-wiki-static/User_Guide/Working_with_ImageJ.html",srcName:"ImageJ User Guide「Working with ImageJ」",version:"User Guide 1.46r 時点の記述に基づき、「標準の保存では」の留保を付して収録した。",lessons:["L03","L07"],terms:["TIFF","Set Scale","LUT（ルックアップテーブル）"]},
{id:"D12-4",title:"保存形式の選択指針：解析用・共有用・提出用を分ける",menu:"File > Save As",body:["形式選択の実務的な指針は、用途ごとにファイルを分けることである。解析用は元のビット深度と校正を保持するTIFF、共有・確認用は相手が開ける形式、提出用は指定された形式という具合に、役割ごとに書き分け、解析用を上書きしない。","特に、型変換や表示範囲の Apply、JPEG保存のような不可逆な操作は、解析用ファイルに対して行わない。これらが必要な場合はコピーに対して行い、ファイル名やフォルダで区別する。"],points:["用途別にファイルを書き分ける","不可逆操作はコピーにだけ適用する","解析用マスターは常に保持する"],caution:"ファイル名が同じで中身の世代が違う状態は、取り違えの温床になる。命名規則で世代と用途を区別すること。",src:"https://imagej.github.io/imagej-wiki-static/User_Guide/Working_with_ImageJ.html",srcName:"ImageJ User Guide「Working with ImageJ」",version:"User Guide 1.46r の形式解説に基づく実務指針（独自まとめ）。現行版でも各形式の性質は同一である。",lessons:["L03"],terms:["TIFF","量子化"]}
]}
];

window.IJDATA2.terms = [
{t:"アクティブ画像",en:"Active Image",aliases:["アクティブイメージ","前面の画像"],cat:"basics",d:"最前面にあり、処理・計測などすべての操作の対象になる画像ウィンドウ。",detail:"ImageJの操作は常にアクティブな1枚に対して実行される。複数画像を開いているときは、タイトルバーの状態で対象を確認することが誤操作防止の基本になる。マクロでは getTitle() で対象を明示できる。",vs:"開いているだけの非アクティブ画像は操作対象にならない点が異なる。",ex:"複製して処理する前に、元画像のウィンドウがアクティブか確認する。",related:[],src:"work"},
{t:"Undo",en:"Undo",aliases:["取り消し","アンドゥ"],cat:"basics",d:"取り消し操作。ImageJでは基本的に直近の画像編集・フィルタ操作に限られる。",detail:"一般的なアプリケーションのような多段階の履歴さかのぼりはできない。破壊的な処理の前に複製や中間保存を行うことが、実質的な「保険」になる。",vs:"多段階 undo が可能な一般的な編集ソフトとは仕様が異なる。",ex:"フィルタを掛け過ぎた場合、直前の1回分だけ取り消せる。",related:["アクティブ画像"],src:"work"},
{t:"Fiji",en:"Fiji",aliases:["フィジー"],cat:"basics",d:"ImageJを土台に、ライフサイエンス向けの多数のプラグインを同梱した配布形態。「Fiji Is Just ImageJ」の略。",detail:"本体の操作体系はImageJと共通で、違いは同梱プラグインと ImageJ Updater による更新管理にある。手順を共有する際は、ImageJかFijiか、同梱プラグインの前提が結果に影響する。",vs:"ImageJ本体そのものとは、プラグイン構成と更新方法が異なる。",ex:"Bio-Formatsや各種解析プラグインが初期状態で使える配布形態として導入する。",related:["プラグイン","ImageJ Updater","Bio-Formats"],src:"work"},
{t:"疑似カラー画像",en:"Pseudocolor Image",aliases:["擬似カラー","シュードカラー"],cat:"basics",d:"単一チャンネルのグレー画像にLUTで色を割り当てた表示。色の違いは強度の違いを表す。",detail:"色は表示のための符号化であり、データは単一チャンネルのままである。そのままRGBへ変換すると、チャンネル分離した定量ができなくなる。",vs:"RGB画像（3チャンネルの実データ）とは異なり、色はLUT由来の表示である。",ex:"蛍光強度をカラースケールで可視化して分布を確認する。",related:["LUT（ルックアップテーブル）","RGB画像"],src:"work"},
{t:"コマンドレコーダ",en:"Command Recorder",aliases:["レコーダ","Recorder","Macros > Record"],cat:"basics",d:"Plugins > Macros > Record。GUI操作を記録し、run()呼び出しからなるマクロを生成する機能。",detail:"自動化の起点であると同時に、メニュー操作が内部コマンドのどれに対応するかを確認する公式な手段でもある。記録されたコードは編集して再利用できる。",vs:"手作業の手順メモとは異なり、そのまま実行可能なコードが得られる。",ex:"閾値処理から粒子解析までの操作を記録し、バッチ処理用マクロの土台にする。",related:[".ijm / マクロファイル"],src:"plug"},
{t:"ピクセル",en:"Pixel",aliases:["画素","picture element"],cat:"basics",d:"画像の最小構成要素。強度（グレー値）を持ち、画像はピクセルの2次元格子として表される。",detail:"ピクセルは「値を持つ格子点」であり、実空間での大きさは空間校正（Set Scale）によって初めて決まる。ピクセル数と実寸は別の概念である。",vs:"ボクセルはスタックにおける3次元版の概念。",ex:"16-bit画像の各ピクセルは0〜65,535の整数値を持つ。",related:["グレー値","ボクセル","Set Scale"],src:"work"},
{t:"グレー値",en:"Gray Value",aliases:["画素値","ピクセル値","輝度値","gray level"],cat:"basics",d:"各ピクセルが保持する数値。検出信号を数値化したもので、それ自体は物理量ではない。",detail:"取得条件（露光・ゲイン・光源）が変われば同じ対象でも値は変わるため、比較は条件をそろえた画像間でのみ意味を持つ。表示の明るさとは別物で、LUTや表示範囲では変わらない。",vs:"表示上の明るさ（表示範囲で変わる）や、校正後の物理量とは異なる。",ex:"蛍光画像で対象領域のグレー値の平均を取り、背景と比較する。",related:["ピクセル","Mean Gray Value","ヒストグラム"],src:"work"},
{t:"8-bit画像",en:"8-bit Image",aliases:["8ビット","256階調"],cat:"types",d:"256階調（0〜255の整数のみ）を表せる画像。",detail:"表示・互換性の面では扱いやすいが、階調が粗く、取得データが16-bitの場合は変換で情報が失われる。演算では範囲外の結果が0や255に丸められる。",vs:"16-bit画像と比べ階調が1/256で、ダイナミックレンジが狭い。",ex:"表示用・提出用への書き出しや、二値化の前提として使う。",related:["16-bit画像","量子化","ダイナミックレンジ"],src:"work"},
{t:"16-bit画像",en:"16-bit Image",aliases:["16ビット","65536階調"],cat:"types",d:"65,536階調（0〜65,535の整数のみ）を表せる画像。符号なし整数として扱われる。",detail:"顕微鏡取得データの標準的な深度。ヒストグラム表示では最小〜最大の範囲を256ビンに分けて集計される。8-bit化すると階調が潰れて戻らない。",vs:"8-bit画像より階調が細かいが、小数や負値は保持できない点は共通。",ex:"蛍光強度の定量は、取得した16-bitのまま行う。",related:["8-bit画像","32-bit画像","ビン（bin）"],src:"work"},
{t:"32-bit画像",en:"32-bit Float Image",aliases:["32ビット","float画像","浮動小数画像"],cat:"types",d:"浮動小数でピクセル値を表す画像。値の範囲に制限がなく、NaNも入り得る。",detail:"演算の中間結果（差分・除算など）を切り捨てずに保持するための型である。Image Calculator の 32-bit Result 指定はこの型で結果を返す。",vs:"整数型と異なり、小数・負値・Infinity/NaNを保持できる。",ex:"背景画像の引き算結果を負値ごと保持してから評価する。",related:["Infinity / NaN","Image Calculator"],src:"work"},
{t:"RGB画像",en:"RGB Image",aliases:["RGBカラー","24-bitカラー"],cat:"types",d:"赤・緑・青の各チャンネルが256値を持つ24-bitカラー画像（alpha付きは32-bit）。",detail:"表示のための表現であり、定量には向かない。チャンネル別に測る場合は Split Channels でグレースケールへ分離する。ヒストグラムは輝度変換後の分布として表示される。",vs:"コンポジット画像とは異なり、チャンネルを分離保持しない。",ex:"カラー写真の取り込みや、提出用の合成図の作成に使う。",related:["チャンネル","コンポジット画像","疑似カラー画像"],src:"work"},
{t:"チャンネル",en:"Channel",aliases:["channel","色チャンネル","蛍光チャンネル"],cat:"types",d:"画像を構成する独立した成分（赤・緑・青や、各蛍光色素）のデータ系列。",detail:"多重染色では1色素＝1チャンネルが基本で、チャンネルごとにグレースケールとして定量する。コンポジット画像やハイパースタックの c 軸として保持される。",vs:"スライス（z方向の断層）やフレーム（t方向）とは別の軸である。",ex:"DAPIとGFPを別チャンネルとして分離し、それぞれ測定する。",related:["コンポジット画像","Merge Channels","ハイパースタック"],src:"color"},
{t:"TIFF",en:"TIFF",aliases:["TIF","Tagged Image File Format"],cat:"types",d:"ImageJのデフォルト形式。8/16/32-bit・RGBに対応し、スケール等のメタデータを保存できる唯一の通常形式。",detail:"可逆であり、空間校正を保持できるため、解析データの保存の標準になる。表示用に他形式へ書き出すと校正は失われる。",vs:"JPEG（非可逆・校正を保持しない）とは保存の性質が正反対に近い。",ex:"解析途中の画像と結果画像をTIFFで保存し、校正を維持する。",related:["Set Scale","Bio-Formats"],src:"work"},
{t:"スタック",en:"Stack",aliases:["stack","画像スタック"],cat:"types",d:"複数の画像（スライス）を1ウィンドウにまとめたもの。全スライスが同サイズ・同ビット深度である必要がある。",detail:"Z方向の断層列として扱うのが典型である。Z投影や Multi Measure など、スタック専用の処理・測定の対象になる。",vs:"ハイパースタックは、スタックにチャンネルと時間の軸を加えた拡張。",ex:"共焦点顕微鏡のZシリーズを開いて投影・測定する。",related:["スライス","ハイパースタック","Z投影","仮想スタック"],src:"work"},
{t:"スライス",en:"Slice",aliases:["slice","断層像"],cat:"types",d:"スタックを構成する1枚の画像。Z方向の位置に対応する。",detail:"スタック内の位置はスライス番号で表される。Z投影の範囲指定や、Multi Measure の測定単位はスライスを基準にする。",vs:"チャンネル（c軸）やフレーム（t軸）とは異なる軸の要素である。",ex:"Z投影の開始・終了スライスを指定して部分投影する。",related:["スタック","ボクセル","Z投影"],src:"work"},
{t:"ハイパースタック",en:"Hyperstack",aliases:["hyperstack","多次元スタック"],cat:"types",d:"x, y, z（深さ）, c（チャンネル）, t（時間）の4D/5Dを扱うスタックの拡張。",detail:"軸の割り当てを取り違えると、チャンネルと時間を混同した解析になる。読み込み時に各軸の意味を確認することが前提になる。",vs:"通常のスタック（zのみ）に対し、c・t の軸が加わる。",ex:"多色蛍光のタイムラプスデータを5次元として開く。",related:["スタック","チャンネル","コンポジット画像"],src:"work"},
{t:"仮想スタック",en:"Virtual Stack",aliases:["virtual stack"],cat:"types",d:"データをディスク上に置くスタック。メモリに収まらない画像列を開けるが読み取り専用。",detail:"大容量データの閲覧・確認には有効だが、画素を書き換える処理は適用できない。処理が必要な部分は通常のスタックとして読み込み直す。",vs:"通常のスタックとは、メモリ常駐かディスク常駐かと、書き換え可否が異なる。",ex:"数千枚の連番画像を仮想スタックで開いて対象範囲を選定する。",related:["スタック"],src:"work"},
{t:"ボクセル",en:"Voxel",aliases:["voxel","体積要素"],cat:"types",d:"スタックにおける3次元格子上の強度値。2D画像のピクセルに対応する概念。",detail:"実空間での大きさは、xy方向の画素サイズと z 間隔の校正によって決まる。3次元での体積・距離の測定では z 間隔の校正が誤差要因になる。",vs:"ピクセルは2次元の格子要素、ボクセルは3次元の格子要素。",ex:"Zスタックの物体積をボクセル数と校正値から算出する。",related:["ピクセル","スタック","Set Scale"],src:"work"},
{t:"コンポジット画像",en:"Composite Image",aliases:["composite","合成画像（チャンネル保持）"],cat:"types",d:"チャンネルを分離保持する画像。各チャンネルは8/16/32-bitでもよく、表示のオン/オフができる。",detail:"Merge Channels で Create Composite を選ぶと生成される。分離保持されているため、チャンネル別の表示切替や再分離・定量が可能である。",vs:"RGB画像とは異なり、チャンネルが混ざっていない。",ex:"3色蛍光をコンポジットで重ね、チャンネルを切り替えながら確認する。",related:["チャンネル","Merge Channels","RGB画像"],src:"color"},
{t:"量子化",en:"Quantization",aliases:["quantization","階調圧縮"],cat:"types",d:"連続的・細かい階調の値を、粗い段階の値へ丸めること。ビット深度を下げるときに起きる。",detail:"16-bit→8-bit変換では65,536階調が256階調へ圧縮され、中間の差は同一値に潰れる。失われた階調は、深度を戻しても復元しない。",vs:"表示範囲の変更（値は不変）とは異なり、データそのものが失われる。",ex:"暗部のわずかな強度差が8-bit化で消える現象として現れる。",related:["8-bit画像","16-bit画像","ダイナミックレンジ"],src:"work"},
{t:"ダイナミックレンジ",en:"Dynamic Range",aliases:["dynamic range","DR","階調範囲"],cat:"types",d:"表現・検出できる最小信号から最大信号までの幅。ビット深度と検出器性能で決まる。",detail:"8-bitでは最大256倍、16-bitでは最大65,536倍の比が表現の上限になる。暗い対象と明るい対象が同居する画像では、この幅が不足すると暗部が潰れるか明部が飽和する。",vs:"ビット深度そのものとは異なり、実際に使えている信号の幅を指す場合もある。",ex:"露光を決める際に、飽和せず暗部も潰れない範囲に収める。",related:["飽和","量子化","16-bit画像"],src:"work"},
{t:"飽和",en:"Saturation",aliases:["saturation","サチュレーション","白飛び"],cat:"types",d:"信号が表現できる上限（8-bitなら255、16-bitなら65,535）に達し、それ以上の差が記録できなくなった状態。",detail:"飽和した領域の値はすべて上限値に張り付くため、強度の比較も形状の評価もできない。取得時の露光・ゲイン調整で避けるのが原則で、後処理では回復できない。整数演算で範囲外の結果が上限に丸められる現象も同種の問題である。",vs:"単に「明るい」こととは異なり、上限に張り付いて差が消えた状態を指す。",ex:"蛍光が強すぎる条件では核内が一様に最大値になり、定量できない。",related:["ダイナミックレンジ","グレー値","Math（Process > Math）"],src:"work"},
{t:"ROI",en:"Region of Interest",aliases:["関心領域","選択範囲","region of interest"],cat:"roi",d:"Region of Interest（関心領域）。ツールで作る選択範囲で、計測や処理の対象を指定する。同時にアクティブなのは1つだけ。",detail:"描いただけでは画像データは変わらない「指定」であり、測定・処理はこの指定を参照して行われる。複数を扱う場合は ROI Manager へ登録する。英語名の略称 ROI がそのまま使われることが多い。",vs:"マスクは画素値で表されたデータ、オーバーレイは非破壊の重ね表示であり、ROIとは性質が異なる。",ex:"細胞の輪郭をなぞってROIを作り、面積とMeanを測る。",related:["ROI Manager","マスク","オーバーレイ"],src:"work"},
{t:"マスク",en:"Mask",aliases:["mask","マスク画像"],cat:"roi",d:"対象と背景を画素値（多くは対象255・背景0）で表した二値の画像データ。",detail:"ROIが「指定」であるのに対し、マスクは保存・演算に使えるデータである。Convert to Mask で閾値設定から生成でき、Image Calculator の論理演算で他の画像と組み合わせられる。",vs:"ROI（一次的な指定）、オーバーレイ（表示）とは異なり、画素値を持つ実データである。",ex:"マスクとのAND演算で、対象領域だけを切り出して測定する。",related:["ROI","Convert to Mask","二値画像（バイナリ）","AND演算（画像）"],src:"bin"},
{t:"ROI Manager",en:"ROI Manager",aliases:["ROIマネージャ","ROIマネージャー"],cat:"roi",d:"Analyze > Tools > ROI Manager。複数の選択を一覧で保持し、計測・描画・保存を行う道具。",detail:"Add（キー「t」）で現在の選択を登録する。Measure で一括測定、Save で .roi / ZIP 保存、More > Multi Measure でスタック全体の測定ができる、ROI運用の中核である。",vs:"単一のアクティブな選択とは異なり、複数ROIの集合を管理する仕組み。",ex:"対象ROIと背景ROIを登録し、まとめてMeasureして差し引く。",related:["ROI",".roiファイル / ROIセットZIP","Multi Measure"],src:"tools"},
{t:".roiファイル / ROIセットZIP",en:".roi File / ROI Set ZIP",aliases:["roiファイル","ROIセット"],cat:"roi",d:"ROI ManagerのSaveで作る保存形式。単体は.roi、複数一括はZIPアーカイブ。Openで読み戻せる。",detail:"画像と一緒に保管することで、別のセッションでも同じ選択集合を再現でき、測定の再現性を担保できる。座標は画像左上原点基準である。",vs:"画像ファイルそのものとは異なり、座標情報だけを保持する。",ex:"解析に使ったROIセットを結果データと一緒に保存する。",related:["ROI Manager","ROI"],src:"tools"},
{t:"Restore Selection",en:"Restore Selection",aliases:["選択の復元"],cat:"roi",d:"消した選択を復元するコマンド。別の画像へ選択を移すときにも使う。",detail:"Edit > Selection にある。元画像で作った選択を、処理後の画像へ同じ座標で移して測定する、といった使い方の基盤になる。",vs:"ROI Managerからの読み戻しとは異なり、直前の選択そのものを復元する。",ex:"二値化した画像へ、元画像で作った選択を復元して重ねる。",related:["ROI","ROI Manager"],src:"work"},
{t:"オーバーレイ",en:"Overlay",aliases:["overlay","重ね表示"],cat:"roi",d:"画像上に非破壊で重ねて表示されるROIなどの要素。アクティブな選択とは別に複数を保持できる。",detail:"画素値を一切変えずに、検出結果の輪郭や注釈を重ねて確認できる。スケールバーをオーバーレイとして描く使い方もあり、この場合は元画素が保持される。",vs:"マスク（画素データ）やアクティブなROI（単一の指定）とは性質が異なる。",ex:"粒子解析で検出した輪郭をオーバーレイ表示し、元画像と照合する。",related:["ROI","マスク","スケールバー"],src:"work"},
{t:"Multi Measure",en:"Multi Measure",aliases:["マルチメジャー"],cat:"roi",d:"ROI Managerの More にある機能。スタックの全画像に対して全ROIを計測し、結果表を作る。",detail:"時間変化やZ方向の変化を、同じROI定義で追跡するための機能である。出力形式で行とROI・スライスの対応が変わるため、本番前に小データで確認するのが安全である。",vs:"Measure（現在の1枚に対する測定）とは対象範囲が異なる。",ex:"タイムラプス全フレームの蛍光強度推移を一括で取得する。",related:["ROI Manager","スタック","Measure"],src:"tools"}
,
{t:"Set Scale",en:"Set Scale",aliases:["空間校正","スケール設定","キャリブレーション"],cat:"measure",d:"Analyzeメニューの空間校正ダイアログ。ピクセル数と既知距離の対応を登録し、結果を実寸単位にする。",detail:"校正の有無で、Areaや長さの結果の単位がピクセル基準か実寸基準かが決まる。Global設定で他画像へ適用される場合があり、倍率違いの画像では誤差の原因になる。校正情報はTIFF/ZIP保存で保持される。",vs:"Set Measurements（記録項目の指定）とは役割が異なる。",ex:"スケールバーの実長を測って µm 単位の校正を登録する。",related:["Area","スケールバー","TIFF"],src:"ana"},
{t:"Set Measurements",en:"Set Measurements",aliases:["計測項目設定"],cat:"measure",d:"Analyzeメニューのダイアログ。MeasureとAnalyze Particlesが記録する計測項目を指定する。",detail:"指定されていない項目は結果表に現れない。「測れない」のではなく「記録されない」仕様であるため、項目が無い場合はまずここを確認する。一連の測定では指定を統一することが比較可能性の前提になる。",vs:"Set Scale（単位の校正）とは役割が異なる。",ex:"面積・Mean・面積率を記録項目として事前に指定する。",related:["Measure","Results表","Mean Gray Value"],src:"ana"},
{t:"Measure",en:"Measure",aliases:["計測","測定"],cat:"measure",d:"Analyze > Measure（キー「m」）。アクティブな選択の計測結果をResults表に1行追加する。",detail:"記録される項目は Set Measurements の指定に従い、単位は Set Scale の校正に従う。選択がない場合は画像全体が対象になる。",vs:"Analyze Particles（オブジェクト単位の自動検出・計測）とは対象の決め方が異なる。",ex:"ROI登録後にMeasureし、結果表へ順に蓄積する。",related:["Set Measurements","Results表","ROI"],src:"ana"},
{t:"Results表",en:"Results Table",aliases:["Results","結果表","リザルツ"],cat:"measure",d:"Measureや粒子解析の結果が1行ずつ貯まる表。保存して他ソフトで利用できる。",detail:"行は測定のたびに追加される。列構成は Set Measurements の指定に依存するため、途中で指定を変えると表の意味が変わる。保存して表計算ソフト等で集計するのが通常の流れである。",vs:"Summary（粒子解析の集計行）とは役割が異なる。通常のResultsは対象ごとの行を持つ。",ex:"全ROIの測定後にResultsを保存し、背景差し引きを表計算で行う。",related:["Measure","Analyze Particles","Set Measurements"],src:"ana"},
{t:"Analyze Particles",en:"Analyze Particles",aliases:["粒子解析","パーティクル解析"],cat:"measure",d:"二値化/閾値済み画像のオブジェクトを走査して数え、それぞれを計測するコマンド。Size範囲外は無視される。",detail:"前提は二値化の品質であり、閾値・Size・Circularity・端の扱いの各条件が結果を全面的に決める。Summarize で個数・合計面積・平均サイズ・面積率（%Area）が Summary に表示される。",vs:"Measure（手動で指定した選択の測定）とは、対象の検出を自動で行う点が異なる。",ex:"閾値→Convert to Mask→粒子解析の流れで細胞数を数える。",related:["閾値処理（Threshold）","Watershed","Results表"],src:"ana"},
{t:"Mean Gray Value",en:"Mean Gray Value",aliases:["平均グレー値","Mean","平均輝度"],cat:"measure",d:"平均グレー値。選択内のグレー値の合計をピクセル数で割った値。",detail:"蛍光画像では平均強度の指標として使われるが、総量ではない。総量は面積×平均（Integrated Density の考え方）で評価する。背景補正では対象の Mean から背景の Mean を差し引く。",vs:"総蛍光量（面積×平均）や Mode（最頻値）とは意味が異なる。",ex:"対象ROIと背景ROIの Mean を測り、差し引いて補正済み強度とする。",related:["グレー値","Set Measurements","ROI Manager"],src:"ana"},
{t:"Area",en:"Area",aliases:["面積"],cat:"measure",d:"選択の面積。Set Scaleで校正済みなら平方ミリメートルなどの校正単位で報告される。",detail:"未校正ではピクセル数（pixel^2）としての値になる。単位の取り違えは、測定単位がおかしい場合の第一の確認点である。",vs:"Area Fraction（面積率、割合）とは異なり、Areaは絶対量である。",ex:"校正済み画像で細胞の面積を µm^2 で報告する。",related:["Set Scale","Set Measurements"],src:"ana"},
{t:"SNR",en:"Signal-to-Noise Ratio",aliases:["信号対ノイズ比","SN比","S/N"],cat:"measure",d:"信号の大きさとノイズの大きさの比。画像の「測れる度合い」を表す基本指標。",detail:"SNRが低い画像では、平滑化で見た目を整えても情報自体は増えない。背景のばらつき（標準偏差）に対する対象信号の比として見積もるのが実務的な捉え方である。取得段階（露光・ゲイン）の設計がSNRを決める。",vs:"単なる明るさやコントラスト（表示で変えられる）とは異なり、データの質の指標である。",ex:"露光条件の異なる画像同士で、定量の信頼度を比べる際の物差しにする。",related:["グレー値","Gaussian Blur","飽和"],src:"work"},
{t:"閾値処理（Threshold）",en:"Threshold",aliases:["しきい値処理","スレッショルド","閾値","thresholding"],cat:"threshold",d:"強度の範囲を指定して対象ピクセルと背景を分ける処理。Image > Adjust > Threshold で行う。",detail:"閾値の指定自体は画素値を変えない「分ける基準の設定」であり、実際に白黒へ変換するのは Apply や二値化コマンドである。「しきい値」とも書かれ、英語では threshold。自動手法（Otsu等）もここで選ぶ。",vs:"二値化（Convert to Mask等、画素値を書き換える変換）とは段階が異なる。",ex:"対象が赤く表示される範囲に閾値を合わせ、粒子解析の前提を作る。",related:["Convert to Mask","Make Binary","Otsu法","二値画像（バイナリ）"],src:"bin"},
{t:"Otsu法",en:"Otsu's Method",aliases:["大津の方法","Otsu"],cat:"threshold",d:"自動閾値の一手法。クラス内分散が最小（クラス間分散が最大）になる閾値を選ぶ。二峰性ヒストグラム向き。",detail:"対象と背景のピークが分かれたヒストグラムで有効に働く。対象が極端に小さい場合や背景が不均一な場合は、前提が崩れて適切な閾値にならない。手法名は結果の条件として記録すべきである。",vs:"他の自動手法（Triangle、Li等）とは最適化の前提が異なる。",ex:"二峰性の明瞭な蛍光画像で自動閾値の第一候補として使う。",related:["閾値処理（Threshold）","ヒストグラム"],src:"bin"},
{t:"Make Binary",en:"Make Binary",aliases:["メイクバイナリ"],cat:"threshold",d:"Process > Binary のコマンド。閾値が設定されていればそれを使い、未設定なら自動で決めて白黒画像へ変換する。",detail:"閾値の決定方法は Convert to Mask と共通（設定済みならその閾値、未設定なら自動決定）。スタックでは表示中スライスの閾値が全スライスへ適用される（imagejdocu の Binary 解説で確認）。",vs:"Convert to Mask との違いは閾値の決め方ではなく、主に結果の形式（マスクとして扱うかどうか）にある。",ex:"閾値を自分で決めずに一括で二値画像化したい場合に使う。",related:["Convert to Mask","閾値処理（Threshold）"],src:"bin"},
{t:"Convert to Mask",en:"Convert to Mask",aliases:["マスクへ変換","コンバートトゥマスク"],cat:"threshold",d:"Process > Binary のコマンド。現在の閾値設定に基づいて白黒のマスク画像へ変換する（閾値が未設定なら自動で決める）。",detail:"実行した時点で画素値が0と255へ書き換わるため、元画像を残すには複製してから実行する。閾値の扱い（設定済みならその閾値、未設定なら自動決定）は Make Binary と共通である。",vs:"Make Binary とは閾値の決め方が共通で、違いは主に結果の形式にある。Threshold（基準の設定のみ）とは段階が異なる。",ex:"閾値を目視で詰めたうえでマスク化し、粒子解析へ渡す。",related:["閾値処理（Threshold）","Make Binary","マスク","Black Background"],src:"bin"},
{t:"Black Background",en:"Black Background",aliases:["ブラックバックグラウンド"],cat:"threshold",d:"Process > Binary > Options の設定。二値画像の作られ方と解釈（どちらが対象か）を決める。",detail:"二値化後の「対象と背景のどちらとして数えるか」に影響する。Threshold ウィンドウ側の Dark Background（暗い背景の解釈指定）とは、所在も意味も別の設定であり、取り違えると結果が全面的に反転する。",vs:"Dark Background（Thresholdウィンドウの設定）とは別物。名前の類似が混同の原因になる。",ex:"白地に黒い対象の画像を二値化する際に解釈を確認する。",related:["Convert to Mask","二値画像（バイナリ）"],src:"bin"},
{t:"二値画像（バイナリ）",en:"Binary Image",aliases:["バイナリ画像","二値化画像","binary"],cat:"threshold",d:"ピクセルが対象と背景の2値だけからなる画像。値としては0と255で表されることが多い。",detail:"粒子解析や形態学処理の入力になる。中間調を持たないため、強度の情報は保持しない。「二値化した画像で強度を測る」ことはできない。",vs:"グレースケール画像（階調を持つ）とは情報の種類が異なる。",ex:"マスクとして保存し、面積率や個数の計測に使う。",related:["Convert to Mask","モルフォロジー演算","Analyze Particles"],src:"bin"},
{t:"Watershed",en:"Watershed",aliases:["ウォーターシェッド","流域分割","分水嶺アルゴリズム"],cat:"threshold",d:"距離マップとその極大点をもとに、接触した粒子同士を分離する処理。Process > Binary > Watershed。",detail:"滑らかで凸形状に近く、重なりの少ない粒子に向く。凹凸の多い対象や大きく重なった対象では、過分割や誤切断が原理的に起きる。分離結果は元画像との照合が必須である。",vs:"閾値処理（対象と背景の分離）とは異なり、対象同士の分離を行う処理。",ex:"軽く接触した細胞同士を分離してから個数を数える。",related:["距離マップ","Analyze Particles","二値画像（バイナリ）"],src:"bin"},
{t:"距離マップ",en:"Distance Map",aliases:["距離画像","EDM","ユークリッド距離マップ"],cat:"threshold",d:"二値画像の各対象ピクセルについて、最も近い背景ピクセルまでの距離を値として持つ画像。",detail:"対象の「太さ」の分布を表し、Watershed 分離の土台になる。極大点が対象の中心部に対応し、1つの対象に複数の極大点が現れる形状では過分割の原因になる。",vs:"元の二値画像（対象か否か）とは異なり、距離という連続量を持つ画像である。",ex:"Watershed の分離位置が妥当かを、距離マップの形状から判断する。",related:["Watershed","二値画像（バイナリ）"],src:"bin"},
{t:"モルフォロジー演算",en:"Morphological Operations",aliases:["形態学処理","形態学演算","morphology"],cat:"threshold",d:"二値画像の形状に対する演算の総称。Erode（侵食）、Dilate（膨張）、Open、Close などがある。",detail:"Open（侵食→膨張）は小さなノイズ対象の除去、Close（膨張→侵食）は穴や切れ目の補填に使う。いずれも形状＝測定対象そのものを変えるため、適用は測定条件として記録する必要がある。",vs:"フィルタ（グレースケールの近傍演算）とは異なり、形状そのものを操作する。",ex:"二値化後の小さなゴミを Open で取り除いてから数える。",related:["二値画像（バイナリ）","Watershed"],src:"bin"},
{t:"Gaussian Blur",en:"Gaussian Blur",aliases:["ガウスぼかし","ガウシアンブラー"],cat:"filter",d:"Process > Filters の平滑化フィルタ。ガウス関数との畳み込みでぼかす。Sigmaはガウス関数の標準偏差σ。",detail:"重み付き平均による平滑化で、σが大きいほど強くぼける。ノイズは減るが、エッジの鈍化とピーク値の低下を伴い、定量値が変わる。Unsharp Mask や背景推定の内部処理としても使われる考え方である。",vs:"Medianフィルタ（中央値）とは置換方法が異なり、外れ値の影響を受けやすい。",ex:"閾値処理の前に弱く掛けてノイズを抑える（条件は記録する）。",related:["Medianフィルタ","Unsharp Mask","Meanフィルタ"],src:"proc"},
{t:"Medianフィルタ",en:"Median Filter",aliases:["メディアンフィルタ","中央値フィルタ"],cat:"filter",d:"各ピクセルを近傍の中央値で置き換えるフィルタ。飛び値ノイズの除去に向く。",detail:"平均系と違い外れ値の影響を受けにくく、エッジの保存性も高い。Radius を大きくすると細い線状構造が消える副作用がある。",vs:"Gaussian Blur（重み付き平均）とは原理とノイズへの特性が異なる。",ex:"塩胡椒状の孤立ノイズを除去してから解析する。",related:["Gaussian Blur","Meanフィルタ"],src:"filt"},
{t:"Unsharp Mask",en:"Unsharp Mask",aliases:["アンシャープマスク","鮮鋭化"],cat:"filter",d:"ぼかしたコピーを差し引いてエッジを強調するフィルタ。Radiusはぼかしのσ、Mask Weightは強さ。",detail:"Mask Weight を大きくしすぎるとエッジ周囲にハロー（過強調の縁）が現れ、ピーク値が跳ね上がる。観察用には有用だが、強調後の画像は強度定量に使えない。",vs:"Sharpen（3×3重み付き平均による強調）とは処理もパラメータも異なる。",ex:"論文図版の見栄えを整える表示用コピーにのみ適用する。",related:["Gaussian Blur","Sharpen"],src:"proc"},
{t:"Meanフィルタ",en:"Mean Filter",aliases:["平均フィルタ","ミーンフィルタ"],cat:"filter",d:"各ピクセルを近傍の平均で置き換える平滑化フィルタ。近傍の大きさはRadiusで指定する。",detail:"最も単純な平滑化で、エッジも一様に鈍る。3×3固定の Smooth とは近傍の大きさが異なる。",vs:"Smooth（3×3固定）や Gaussian Blur（重み付き）とは近傍の扱いが異なる。",ex:"弱い平滑化で全体の粒状感を抑える。",related:["Smooth","Gaussian Blur","Medianフィルタ"],src:"filt"},
{t:"Smooth",en:"Smooth",aliases:["スムーズ"],cat:"filter",d:"Processメニューの平滑化。各ピクセルを3×3近傍の平均で置き換える。",detail:"パラメータを持たない簡易な平滑化で、繰り返し適用すると徐々に強くぼける。条件を細かく管理したい場合は Gaussian Blur 等を使う。",vs:"Meanフィルタとは近傍サイズの指定方法が異なる。",ex:"軽いノイズ低減を手早く行う。",related:["Meanフィルタ","Gaussian Blur"],src:"proc"},
{t:"Sharpen",en:"Sharpen",aliases:["シャープ化"],cat:"filter",d:"Processメニューの強調フィルタ。3×3の重み付き平均でコントラストとディテールを強調する（ノイズも強調し得る）。",detail:"パラメータを持たない強調で、ノイズの多い画像ではノイズも際立つ。強さの調整が必要な場合は Unsharp Mask を使う。",vs:"Unsharp Mask（ぼかし差し引き＋パラメータ調整）とは方式が異なる。",ex:"観察用の画像で輪郭を際立たせる。",related:["Unsharp Mask","Find Edges"],src:"proc"},
{t:"Find Edges",en:"Find Edges",aliases:["エッジ検出","ファインドエッジ"],cat:"filter",d:"Processメニューのエッジ検出。Sobel演算子で強度の急変部を際立たせる。",detail:"輪郭の抽出や、形状の確認に使う可視化系の処理である。出力はエッジの強さの画像であり、元の強度情報は保持しない。",vs:"平滑化フィルタ（変動を抑える）とは逆方向の処理である。",ex:"対象の輪郭形状を目視で確認する。",related:["Sharpen"],src:"proc"},
{t:"PSF",en:"Point Spread Function",aliases:["点像分布関数","点広がり関数","point spread function"],cat:"filter",d:"点光源が光学系を通して画像上でどのように広がって写るかを表す分布。像のぼけの性質を決める。",detail:"実際の像は、対象とPSFの畳み込みとして表される。したがって顕微鏡像の「ぼけ」は対象の性質ではなく光学系の応答であり、近接した対象同士はPSFの広がりの範囲で分離できなくなる。",vs:"ピクセルサイズ（サンプリング間隔）とは別の、光学側の分解能要因である。",ex:"2つの蛍光点が分離できない場合に、PSFの広がりを原因として検討する。",related:["デコンボリューション","Gaussian Blur"],src:"work"},
{t:"デコンボリューション",en:"Deconvolution",aliases:["deconvolution","逆畳み込み"],cat:"filter",d:"PSFによるぼけ（畳み込み）を逆方向に補正し、像の鮮明さと定量性を回復しようとする処理。",detail:"PSFの正確な把握が前提であり、不適切な適用はリンギング等の人工的な構造を生む。ImageJ/Fijiでは専用プラグインを用いる領域であり、標準フィルタによる「鮮鋭化」とは目的も原理も異なる。",vs:"Unsharp Mask（見た目のエッジ強調）とは異なり、光学応答の逆補正を目的とする。",ex:"共焦点・ワイドフィールド像のぼけを、測定PSFを用いて補正する。",related:["PSF","Unsharp Mask"],src:"work"}
,
{t:"ヒストグラム",en:"Histogram",aliases:["histogram","度数分布"],cat:"hist",d:"グレー値ごとのピクセル数の分布。横軸がグレー値、縦軸がピクセル数。Count/Mean/Mode等も表示される。",detail:"分布の形から、飽和の有無（端への張り付き）、背景ピークの位置、対象と背景の分離のしやすさを読み取る。RGB画像では輝度変換後の分布、16-bit画像では256ビンへの集計として表示される。",vs:"測定結果そのものとは異なり、分布の可視化である。",ex:"飽和しているかどうかを、上限側のピークで確認する。",related:["ビン（bin）","Mode（最頻値）","Brightness/Contrast"],src:"hist"},
{t:"LUT（ルックアップテーブル）",en:"Lookup Table (LUT)",aliases:["LUT","ルックアップテーブル","カラーテーブル"],cat:"hist",d:"グレー値と表示色（赤・緑・青の値）の対応表。疑似カラー表示の土台になる。",detail:"LUTの変更は表示だけを変え、画素値と測定結果には影響しない。表示の見た目とデータの区別をつけるための基本概念である。",vs:"画素値そのものや、Brightness/Contrast（表示範囲の指定）とは異なる仕組み。",ex:"グレースケール表示を疑似カラー表示に切り替えて分布を見やすくする。",related:["疑似カラー画像","Brightness/Contrast"],src:"work"},
{t:"Mode（最頻値）",en:"Mode",aliases:["モード","最頻値"],cat:"hist",d:"選択内で最も頻繁に現れるグレー値。ヒストグラムの最も高いピークに対応する。",detail:"多くの画像では背景のグレー値が Mode になる。背景レベルの目安として使えるが、対象が画面の大半を占める画像では背景を表さない。",vs:"Mean（平均）とは異なり、最も多い値を指す。",ex:"背景の代表値をざっくり把握する。",related:["ヒストグラム","Mean Gray Value"],src:"ana"},
{t:"Brightness/Contrast",en:"Brightness/Contrast",aliases:["明るさ/コントラスト","B&C","表示範囲"],cat:"hist",d:"Image > Adjust の表示範囲調整。ヒストグラムを見ながら表示の明暗範囲を変えるための道具。",detail:"通常の調整は表示だけを変え、画素値は変わらない。Apply で反映させた場合に限り値が書き換わり、範囲外の階調が失われる。",vs:"Gamma補正（画素値への非線形変換）とは異なり、原則として表示のみの調整である。",ex:"暗い画像を、データを変えずに見やすい表示にする。",related:["ヒストグラム","LUT（ルックアップテーブル）","Gamma"],src:"hist"},
{t:"ビン（bin）",en:"Bin",aliases:["bin","階級","区間"],cat:"hist",d:"ヒストグラムの集計区間。16-bit画像では最小〜最大の範囲を256ビンに分けて集計する。",detail:"16-bitのヒストグラム表示は、65,536階調をそのままではなく256区間に丸めた概観である。細部の分布を見る目的には向かない点に注意する。",vs:"階調そのもの（65,536段階）とは異なり、表示上の集計単位である。",ex:"16-bit画像のヒストグラムの粗さの理由を理解する。",related:["ヒストグラム","16-bit画像"],src:"hist"},
{t:"Image Calculator",en:"Image Calculator",aliases:["画像計算機","イメージカルキュレータ"],cat:"calc",d:"Processメニューのコマンド。2枚の画像の間で算術・論理演算を行う。32-bit Result指定で浮動小数化してから演算する。",detail:"演算子は加減乗除やAND/ORなど13種。差分・背景引き算・マスク適用の基盤になる。位置の対応した画像同士で使うことが前提である。",vs:"Math（定数との演算）とは異なり、画像同士の演算を行う。",ex:"原画像から背景画像をSubtractしてムラを除く。",related:["Math（Process > Math）","AND演算（画像）","背景差し引き","32-bit画像"],src:"calc"},
{t:"Math（Process > Math）",en:"Math",aliases:["数学演算","定数演算"],cat:"calc",d:"各ピクセルに定数を加減乗除等するコマンド群。8-bitでは結果は0〜255に丸められる。",detail:"Add、Subtract、Multiply、Divide、Gamma などのサブコマンドを持つ。整数型では範囲外が飽和するため、演算の前に32-bit化の要否を判断することが重要である。",vs:"Image Calculator（画像同士）とは演算の相手が異なる。",ex:"全体のオフセットを引いて基準をそろえる。",related:["Image Calculator","Gamma","飽和"],src:"math"},
{t:"Gamma",en:"Gamma",aliases:["ガンマ補正","ガンマ値"],cat:"calc",d:"Mathのガンマ補正。8-bitでは f(p)=(p/255)^gamma×255、gammaの範囲は0.05〜5.0。16-bitでは最小値・最大値でスケーリング。",detail:"非線形の階調変換であり、強度の比例関係を崩す。同じ gamma でも画像の値域で結果の対応が違う（特に16-bit）。表示調整用であり、補正後の画像は定量に使えない。",vs:"Brightness/Contrast（表示のみ）とは異なり、画素値を書き換える変換である。",ex:"表示用コピーの中間調を持ち上げる。",related:["Math（Process > Math）","Brightness/Contrast"],src:"math"},
{t:"Infinity / NaN",en:"Infinity / NaN",aliases:["無限大","非数","Inf"],cat:"calc",d:"32-bit浮動小数の特殊な値。ゼロ除算ではInfinity、0÷0ではNaNになる。",detail:"標準設定では、画像演算のゼロ除算はこの形で結果に現れる。NaNを含む領域の統計はその影響を受けるため、除算系の演算後は値の点検が必要である。",vs:"整数型では現れず、範囲外は上限・下限へ丸められる点が異なる。",ex:"背景がゼロの領域で除算した結果を点検する。",related:["32-bit画像","Image Calculator"],src:"calc"},
{t:"背景差し引き",en:"Background Subtraction (manual)",aliases:["背景引き算","バックグラウンド差し引き"],cat:"calc",d:"原画像から背景とみなす画像（ぼかした版など）をSubtractで引く処理の組み立て方。",detail:"Image Calculator の Subtract で自前で組む方法と、専用の Subtract Background コマンドを使う方法がある。どちらも「引く量の推定方法」が結果を決める。",vs:"Subtract Background（ローリングボールで背景を推定する専用コマンド）とは推定方法が異なる。",ex:"別途用意した背景画像を引いて照明ムラを除く。",related:["Subtract Background","Image Calculator"],src:"calc"},
{t:"AND演算（画像）",en:"AND Operation",aliases:["AND","論理積"],cat:"calc",d:"Image Calculatorの論理演算の1つ。2画像のビット単位ANDを取り、マスクの共通部分抽出などに使う。",detail:"マスクとの組み合わせで「対象領域だけを残す」処理の基盤になる。グレースケール同士ではビット単位の演算になるため、意図した結果か小さな例で確認してから使うこと。",vs:"算術演算（Add/Subtract等）とは性質が異なる論理演算である。",ex:"2つのマスクの共通部分を抽出する。",related:["Image Calculator","マスク"],src:"calc"},
{t:".ijm / マクロファイル",en:"Macro File (.ijm)",aliases:["ijm","マクロファイル"],cat:"macro",d:"ImageJマクロを保存するテキストファイル。Plugins > Macros から実行・インストールできる。",detail:"テキストであるため、条件の差分管理や共有が容易である。手順の再現性を担保する成果物として、画像・結果と一緒に保管する。",vs:"プラグイン（Java/.class）とは異なり、コンパイル不要のテキストである。",ex:"確定した解析手順を .ijm として版管理する。",related:["コマンドレコーダ","プラグイン"],src:"plug"},
{t:"バッチ処理",en:"Batch Processing",aliases:["一括処理","batch processing"],cat:"macro",d:"フォルダ内の多数の画像に同じ処理（マクロなど）を一括適用し、出力フォルダへ保存する運用。",detail:"人手の介在を減らし、条件の統一を保証する運用形態である。代表的な実装が Process > Batch > Macro で、出力先の指定が保存の前提になる。",vs:"バッチモード（setBatchMode、表示の省略）とは別の概念である。",ex:"実験の全画像に同じ背景補正と測定を適用する。",related:["バッチマクロ（Process > Batch）"],src:"plug"},
{t:"プラグイン",en:"Plugin",aliases:["plugin","拡張モジュール"],cat:"plugin",d:"Javaで書かれ .class にコンパイルされた拡張モジュール。pluginsフォルダに入れるとメニューに載る。",detail:"ファイル名のアンダースコアなど、メニューに載るための命名条件がある。標準コマンドの多くも ij.jar 内の内部プラグインとして実装されており、本体と拡張の境界は連続している。",vs:"マクロ（テキスト/.ijm）とは実装言語と配布形式が異なる。",ex:"専用の解析機能をpluginsフォルダへ追加して使う。",related:["ij.jar",".ijm / マクロファイル","ImageJ Updater"],src:"plug"},
{t:"ij.jar",en:"ij.jar",aliases:["ImageJ本体","本体JAR"],cat:"plugin",d:"ImageJ本体のJARファイル。標準コマンドの多くが内部プラグインとしてここに実装されている。",detail:"本体のバージョンは ij.jar の版に対応する。動作の差異を調べる際は、ImageJのバージョン表記と対応づけて記録することが重要である。",vs:"外部プラグイン（pluginsフォルダ側）とは配置場所が異なる。",ex:"バージョン起因の挙動差を切り分ける際の確認対象になる。",related:["プラグイン"],src:"plug"},
{t:"Bio-Formats",en:"Bio-Formats",aliases:["バイオフォーマッツ","BioFormats"],cat:"plugin",d:"多数のライフサイエンス形式を読み書きするライブラリ/プラグイン群。ImporterでメタデータをOMEモデルに標準化する。",detail:"メーカー形式の画像と取得メタデータ（画素サイズ、チャンネル構成等）を正しく読み込むための基盤である。Fijiでは File > Open に統合され、更新は ImageJ Updater を使うことが推奨される。",vs:"ImageJ標準の読み込み（ネイティブ形式のみ）とは対応範囲が異なる。",ex:"顕微鏡メーカー形式をメタデータごと開く。",related:["ImageJ Updater","TIFF"],src:"bio"},
{t:"ImageJ Updater",en:"ImageJ Updater",aliases:["アップデータ","Updater"],cat:"plugin",d:"Fijiで更新サイトとプラグインを管理する仕組み。Bio-Formatsの更新もこちらを使うことが推奨される。",detail:"本体とプラグインの更新を一元管理する。更新により挙動が変わり得るため、重要な解析の途中での一括更新は避け、更新後は代表データで再検証する。",vs:"個別にファイルを差し替える手動管理とは、再現性・追跡性の面で異なる。",ex:"更新サイトを追加して新しい解析プラグインを導入する。",related:["更新サイト（Update Site）","Bio-Formats","Fiji"],src:"bio"},
{t:"更新サイト（Update Site）",en:"Update Site",aliases:["update site","アップデートサイト"],cat:"plugin",d:"Updaterに登録してプラグイン一式を配布・更新するための仕組み。",detail:"有効化した更新サイトの組み合わせが、その環境で使える機能を決める。手順共有の際は、有効な更新サイトも条件として記録すべきである。",vs:"単体のプラグインファイルの配布とは、管理単位が異なる。",ex:"研究室で共通の更新サイト構成にそろえて環境を統一する。",related:["ImageJ Updater","プラグイン"],src:"bio"},
{t:"StartupMacros",en:"StartupMacros",aliases:["スタートアップマクロ"],cat:"plugin",d:"ImageJ/macrosフォルダのStartupMacros.txt。起動時に自動でインストールされるマクロ群のファイル。",detail:"よく使うマクロを起動直後から使えるようにするための仕組みである。共有環境では、ここに何が入っているかが操作感の差になる。",vs:"通常の .ijm（手動で実行する）とは、読み込みのタイミングが異なる。",ex:"共通の測定マクロを起動時に自動で読み込む。",related:[".ijm / マクロファイル","プラグイン"],src:"plug"},
{t:"Subtract Background",en:"Subtract Background",aliases:["背景補正コマンド","サブトラクトバックグラウンド"],cat:"flow",d:"Processメニューの背景補正。ローリングボールで推定した滑らかな背景を差し引いて背景を均す。",detail:"半径の目安は型で異なり、8-bit/RGBでは背景でない最大対象の半径以上、16-bit（0〜65535）では0.2〜5程度が典型値とされる。明背景＋暗対象では Light Background を指定する。補正は信号自体も変えるため、条件の統一と記録が必須である。",vs:"背景差し引き（Image Calculatorで自前で組む引き算）とは背景の推定方法が異なる。",ex:"照明ムラのある画像の閾値処理の前処理として使う。",related:["ローリングボール半径","背景差し引き"],src:"subbg"},
{t:"ローリングボール半径",en:"Rolling Ball Radius",aliases:["rolling ball radius","ボール半径"],cat:"flow",d:"Subtract Backgroundで背景推定に使うボールの半径。8-bit/RGBでは背景ではない最大対象の半径以上の大きさに設定する。",detail:"小さすぎると対象自体が背景として差し引かれる。画素値の範囲が大きく異なる画像では、半径は値の範囲に反比例する方向へ調整する。Sliding Paraboloid 選択時は放物面の曲率半径として解釈される。",vs:"フィルタの Radius（近傍の大きさ）とは、意味する対象が異なる。",ex:"対象の大きさを見積もってから半径を決め、Previewで確認する。",related:["Subtract Background"],src:"subbg"},
{t:"Z投影",en:"Z Projection",aliases:["Zプロジェクション","Z Project","z projection"],cat:"flow",d:"Image > Stacks > Z Project。スタックをZ軸方向に投影して1枚にまとめる処理。最大値・平均・合計などの方式がある。",detail:"方式は平均・最大・最小・合計・標準偏差・中央値の6種で、方式によって画素値の意味が変わる。投影範囲の指定も条件の一部であり、方式名とあわせて記録する。",vs:"単一スライスの抽出とは異なり、全（または指定範囲の）スライスを集約する処理である。",ex:"蛍光の全体構造を Maximum 投影で1枚にまとめる。",related:["スタック","スライス"],src:"zproj"},
{t:"スケールバー",en:"Scale Bar",aliases:["scale bar","バー","縮尺バー"],cat:"flow",d:"Analyze > Tools > Scale Barで描く、校正単位で長さを示すラベル付きバー。Set Scaleによる校正が前提になる。",detail:"Widthは校正単位でのバーの長さ、Heightはピクセル単位の太さを指定する。画像に空間校正が設定されていることが前提で、既に校正済みの画像では Set Scale のやり直しは不要である。オーバーレイとして描けば元画素は保持される。",vs:"単なる図形の線とは異なり、校正に基づく実長を表す。",ex:"論文図版に10 µm のスケールバーを入れる。",related:["Set Scale","オーバーレイ"],src:"tools"},
{t:"Merge Channels",en:"Merge Channels",aliases:["チャンネル合成","マージチャンネル"],cat:"flow",d:"Image > Colorのコマンド。開いているグレースケール画像を各チャンネルに割り当てて合成画像を作る。",detail:"Create Composite を選ぶとチャンネルを分離保持するコンポジット画像になり、表示のオン/オフや再分離ができる。割り当てミスはチャンネルの取り違えに直結する。",vs:"Split Channels（分離）とは逆の操作。RGBへの焼き込みとは異なり、コンポジットでは分離が保持される。",ex:"3色の蛍光画像を合成して重なりを確認する。",related:["コンポジット画像","チャンネル"],src:"color"},
{t:"バッチマクロ（Process > Batch）",en:"Batch Macro (Process > Batch)",aliases:["Batch > Macro","バッチ > マクロ"],cat:"flow",d:"Process > Batch > Macro。入力フォルダ内の全画像に同じマクロを適用し、出力フォルダへ保存する仕組み。",detail:"出力フォルダを指定しないと、バッチ機能による自動保存はされない（マクロ内に保存処理を書いた場合はその限りではない）。同名出力は上書きされることがあるため、出力は入力と別フォルダにし、元画像のバックアップを残す。",vs:"setBatchMode()（表示を止める関数）とは別の仕組みである。",ex:"フォルダ内の全画像に同じ測定マクロを適用する。",related:["バッチ処理",".ijm / マクロファイル"],src:"batch"}
];
